Definition RBankSelect
(mode : mword 5) (usr : Z) (fiq : Z) (irq : Z) (svc : Z) (abt : Z) (und : Z) (hyp : Z)
:
M ({n : Z & ArithFact ((n =? usr) ||
  ((n =? fiq) || ((n =? irq) || ((n =? svc) || ((n =? abt) || ((n =? und) || (n =? hyp)))))))}) :=
   let _pat_ := mode in
   (if eq_vec _pat_ M32_User then returnm (build_ex usr)
    else if eq_vec _pat_ M32_FIQ then returnm (build_ex fiq)
    else if eq_vec _pat_ M32_IRQ then returnm (build_ex irq)
    else if eq_vec _pat_ M32_Svc then returnm (build_ex svc)
    else if eq_vec _pat_ M32_Abort then returnm (build_ex abt)
    else if eq_vec _pat_ M32_Hyp then returnm (build_ex hyp)
    else if eq_vec _pat_ M32_Undef then returnm (build_ex und)
    else if eq_vec _pat_ M32_System then returnm (build_ex usr)
    else
      assert_exp' false "Pattern match failure at model/aarch_mem.sail 1044:4 - 1053:5" >>= fun _ =>
      exit tt)
    : M ({n : Z & ArithFact ((n =? usr) ||
     ((n =? fiq) || ((n =? irq) || ((n =? svc) || ((n =? abt) || ((n =? und) || (n =? hyp)))))))}).

