Definition ConstrainUnpredictable (which : Unpredictable) : M (Constraint) :=
   (match which with
    | Unpredictable_WBOVERLAPLD => returnm Constraint_WBSUPPRESS
    | Unpredictable_WBOVERLAPST => returnm Constraint_NONE
    | Unpredictable_LDPOVERLAP => returnm Constraint_UNDEF
    | Unpredictable_BASEOVERLAP => returnm Constraint_NONE
    | Unpredictable_DATAOVERLAP => returnm Constraint_NONE
    | Unpredictable_DEVPAGE2 => returnm Constraint_FAULT
    | Unpredictable_INSTRDEVICE => returnm Constraint_NONE
    | Unpredictable_RESCPACR => returnm Constraint_UNKNOWN
    | Unpredictable_RESMAIR => returnm Constraint_UNKNOWN
    | Unpredictable_RESTEXCB => returnm Constraint_UNKNOWN
    | Unpredictable_RESDACR => returnm Constraint_UNKNOWN
    | Unpredictable_RESPRRR => returnm Constraint_UNKNOWN
    | Unpredictable_RESVTCRS => returnm Constraint_UNKNOWN
    | Unpredictable_RESTnSZ => returnm Constraint_FORCE
    | Unpredictable_OORTnSZ => returnm Constraint_FORCE
    | Unpredictable_LARGEIPA =>
       returnm (if __unpred_tsize_aborts then Constraint_FAULT else Constraint_FORCE)
    | Unpredictable_ESRCONDPASS => returnm Constraint_FALSE
    | Unpredictable_ILZEROIT => returnm Constraint_FALSE
    | Unpredictable_ILZEROT => returnm Constraint_FALSE
    | Unpredictable_BPVECTORCATCHPRI => returnm Constraint_TRUE
    | Unpredictable_VCMATCHHALF => returnm Constraint_FALSE
    | Unpredictable_VCMATCHDAPA => returnm Constraint_FALSE
    | Unpredictable_WPMASKANDBAS => returnm Constraint_FALSE
    | Unpredictable_WPBASCONTIGUOUS => returnm Constraint_FALSE
    | Unpredictable_RESWPMASK => returnm Constraint_DISABLED
    | Unpredictable_WPMASKEDBITS => returnm Constraint_FALSE
    | Unpredictable_RESBPWPCTRL => returnm Constraint_DISABLED
    | Unpredictable_BPNOTIMPL => returnm Constraint_DISABLED
    | Unpredictable_RESBPTYPE => returnm Constraint_DISABLED
    | Unpredictable_BPNOTCTXCMP => returnm Constraint_DISABLED
    | Unpredictable_BPMATCHHALF => returnm Constraint_FALSE
    | Unpredictable_BPMISMATCHHALF => returnm Constraint_FALSE
    | Unpredictable_RESTARTALIGNPC => returnm Constraint_FALSE
    | Unpredictable_RESTARTZEROUPPERPC => returnm Constraint_TRUE
    | Unpredictable_ZEROUPPER => returnm Constraint_TRUE
    | Unpredictable_ERETZEROUPPERPC => returnm Constraint_TRUE
    | Unpredictable_A32FORCEALIGNPC => returnm Constraint_FALSE
    | Unpredictable_SMD => returnm Constraint_UNDEF
    | Unpredictable_AFUPDATE => returnm Constraint_TRUE
