Fixpoint _rec_BigEndianReverse {width : Z} (value_name : mword width) (_reclimit : Z)
`{ArithFact (width >=? 0)} (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (mword width).
exact (
   assert_exp' (Z.geb _reclimit 0) "recursion limit reached" >>= fun _ =>
   assert_exp' (orb (Z.eqb (length value_name) 8)
                  (orb (Z.eqb (length value_name) 16)
                     (orb (Z.eqb (length value_name) 32)
                        (orb (Z.eqb (length value_name) 64) (Z.eqb (length value_name) 128))))) "model/aarch_mem.sail 2578:83 - 2578:84" >>= fun _ =>
   let half := projT1 (ediv_with_eq (length value_name) 2) in
   (if sumbool_of_bool (Z.eqb (length value_name) 8) then returnm value_name
    else
      (_rec_BigEndianReverse _ (slice value_name 0 half) (Z.sub _reclimit 1) _ (_limit_reduces _acc)) >>= fun w__0 : mword (ZEuclid.div width 2) =>
      (_rec_BigEndianReverse _ (slice value_name half (Z.sub (length value_name) half))
         (Z.sub _reclimit 1) _ (_limit_reduces _acc)) >>= fun w__1 : mword (width - ZEuclid.div width 2) =>
      returnm (autocast (autocast (concat_vec w__0 w__1))))
    : M (mword width)
).
Defined.


Definition BigEndianReverse {width : Z} (x : mword width) `{ArithFact (width >=? 0)}
: M (mword width) :=
   (_rec_BigEndianReverse x ((length x)  : Z) (Zwf_guarded _))  : M (mword width).

