Definition mapvpmw (vpartid : Z) : M (mword 16) :=
   (undefined_bitvector 64) >>= fun w__0 : mword 64 =>
   let vpmw : bits 64 := w__0  : bits 64 in
   let wd := projT1 (ediv_with_eq vpartid 4) in
   let l__211 := wd in
   (if sumbool_of_bool (Z.eqb l__211 0) then
      ((read_reg MPAMVPM0_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 1) then
      ((read_reg MPAMVPM1_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 2) then
      ((read_reg MPAMVPM2_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 3) then
      ((read_reg MPAMVPM3_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 4) then
      ((read_reg MPAMVPM4_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 5) then
      ((read_reg MPAMVPM5_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 6) then
      ((read_reg MPAMVPM6_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else if sumbool_of_bool (Z.eqb l__211 7) then
      ((read_reg MPAMVPM7_EL2_ref)  : M (mword 64))
       : M (mword 64)
    else
      let vpmw : bits 64 := zeros 64 in
      returnm vpmw) >>= fun vpmw : mword 64 =>
   let vpmw := vpmw in
   let vpme_lsb := Z.mul (projT1 (emod_with_eq vpartid 4)) 16 in
   returnm (slice vpmw vpme_lsb 16).

