Definition __IMPDEF_bits_map (N : Z) (x : string) `{ArithFact (N >=? 0)} : M (mword N) :=
   catch_early_return
     ((match tt with
       | tt =>
          (if generic_eq x "Virtual Asynchronous Abort ExT bit" then
             (early_return ((zeros (projT1 (__id N)))  : mword N) : MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "FPEXC.EN value when TGE==1 and RW==0" then
             (early_return ((__GetSlice_int N 1 0)  : mword N) : MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "MPAM version" then
             (early_return ((__GetSlice_int N (projT1 (uint CFG_ID_AA64PFR0_EL1_MPAM)) 0)
              : mword N) :
               MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "MPAM maximum PARTID" then
             (early_return ((__GetSlice_int N (projT1 (uint __mpam_partid_max)) 0)
              : mword N) :
               MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "MPAM maximum PMG" then
             (early_return ((__GetSlice_int N (projT1 (uint __mpam_pmg_max)) 0)
              : mword N) :
               MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "Has MPAMHCR_EL2" then
             (early_return ((if __mpam_has_hcr then __GetSlice_int N 1 0
                             else zeros (projT1 (__id N)))
              : mword N) :
               MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "MPAM maximum VPMR" then
             (early_return ((__GetSlice_int N (projT1 (uint __mpam_vpmr_max)) 0)
              : mword N) :
               MR (mword N) (mword N))
              : MR (mword N) _
           else if generic_eq x "reset vector address" then
             (early_return ((slice CFG_RVBAR 0 N)  : mword N) : MR (mword N) (mword N))
              : MR (mword N) _
           else liftR (throw (Error_Implementation_Defined "Unrecognized bits(N)")))
           : MR (mword N) _
       end)
      : MR (mword N) _).

Definition __IMPDEF_bits (N : Z) (x : string) `{ArithFact (N >=? 0)} : M (mword N) :=
   (__IMPDEF_bits_map N x)  : M (mword N).

