Definition TransformTag (vaddr : mword 64) : M (mword 4) :=
   let vtag : bits 4 := slice vaddr 56 4 in
   (ZeroExtend__1 4 (vec_of_bits [access_vec_dec vaddr 55]  : mword 1)) >>= fun tagdelta : bits 4 =>
   let ptag : bits 4 := add_vec vtag tagdelta in
   returnm ptag.

Definition LSR_C {N : Z} (x : mword N) (shift : Z) `{ArithFact (N >=? 0)} : M ((mword N * mword 1)) :=
   assert_exp' (Z.gtb shift 0) "model/aarch_mem.sail 3019:20 - 3019:21" >>= fun _ =>
   let shift := if sumbool_of_bool (Z.gtb shift (length x)) then length x else shift in
   (ZeroExtend__0 x (Z.add shift (length x))) >>= fun extended_x : bits (shift + N) =>
   let result : bits N := slice extended_x shift (length x) in
   let carry_out : bits 1 := (vec_of_bits [access_vec_dec extended_x (Z.sub shift 1)]  : mword 1) in
   returnm (result, carry_out).

Definition LSR {N : Z} (x : mword N) (shift : Z) `{ArithFact ((shift >=? 0) && (N >=? 0))}
: M (mword N) :=
   assert_exp' (Z.geb shift 0) "model/aarch_mem.sail 3031:21 - 3031:22" >>= fun _ =>
   (undefined_bitvector 1) >>= fun w__0 : mword 1 =>
   let __anon1 : bits 1 := w__0  : bits 1 in
   (undefined_bitvector (length x)) >>= fun w__1 : mword N =>
   let result : bits N := w__1  : bits N in
   (if sumbool_of_bool (Z.eqb shift 0) then returnm x
    else
      (LSR_C x shift) >>= fun w__2 : (mword N * mword 1) =>
      let '(tup__0, tup__1) := w__2  : (mword N * mword 1) in
      let result : bits N := tup__0 in
      let __anon1 : bits 1 := tup__1 in
      returnm result)
    : M (mword N).

