Definition AArch64_PhysicalSErrorSyndrome (implicit_esb : bool) : mword 25 :=
   let syndrome : bits 25 := zeros 25 in
   let syndrome : bits 25 := set_slice 25 1 syndrome 24 ('b"0"  : mword 1) in
   let syndrome : bits 25 :=
     set_slice 25 1 syndrome 13
       (if sumbool_of_bool implicit_esb then 'b"1"  : mword 1
        else 'b"0"  : mword 1) in
   let syndrome : mword 25 :=
     match (AsynchronousErrorType tt) with
     | AsyncErrorType_UC => set_slice 25 3 syndrome 10 ('b"000"  : mword 3)
     | AsyncErrorType_UEU => set_slice 25 3 syndrome 10 ('b"001"  : mword 3)
     | AsyncErrorType_UEO => set_slice 25 3 syndrome 10 ('b"010"  : mword 3)
     | AsyncErrorType_UER => set_slice 25 3 syndrome 10 ('b"011"  : mword 3)
     | AsyncErrorType_CE => set_slice 25 3 syndrome 10 ('b"110"  : mword 3)
     end in
   set_slice 25 6 syndrome 0 ('b"010001"  : mword 6).

