           let '_ :=
             (prerr "TODO: GTE External observer requires 'current' security state
")
              : unit in
           currentNS in
       let NS := NS in
       read_reg _GTEExtObsAccess_ref >>= fun w__7 : vec (mword 16) 256 =>
       let p__561 := slice (vector_access_B w__7 i) 0 3 in
       let _pat_ := p__561 in
