Definition MAP_vPARTID (vpartid : mword 16) : M ((mword 16 * bool)) :=
   (undefined_bitvector 16) >>= fun w__0 : mword 16 =>
   let ret : bits 16 := w__0  : bits 16 in
   (undefined_bool tt) >>= fun w__1 : bool =>
   let err : bool := w__1  : bool in
   let virt : Z := projT1 (uint vpartid) in
   ((read_reg MPAMIDR_EL1_ref)  : M (mword 64)) >>= fun w__2 : mword 64 =>
   let vmprmax := projT1 (uint (slice w__2 18 3)) in
   let vpartid_max := Z.add (Z.mul 4 vmprmax) 3 in
   let virt : Z :=
     if sumbool_of_bool (Z.gtb virt vpartid_max) then
       projT1
       (emod_with_eq virt (Z.add vpartid_max 1))
     else virt in
   ((read_reg MPAMVPMV_EL2_ref)  : M (mword 32)) >>= fun w__3 : mword 32 =>
   (if eq_vec (vec_of_bits [access_vec_dec w__3 virt]  : mword 1) ('b"1"  : mword 1) then
      (mapvpmw virt) >>= fun w__4 : mword 16 =>
      let ret : bits 16 := w__4 in
      let err : bool := false in
      returnm (err, ret)
    else
      ((read_reg MPAMVPMV_EL2_ref)  : M (mword 32)) >>= fun w__5 : mword 32 =>
      (if eq_vec (vec_of_bits [access_vec_dec w__5 0]  : mword 1) ('b"1"  : mword 1) then
         ((read_reg MPAMVPM0_EL2_ref)  : M (mword 64)) >>= fun w__6 : mword 64 =>
         let ret : bits 16 := slice w__6 0 16 in
         let err : bool := false in
         returnm (err, ret)
       else
         let ret : bits 16 := DefaultPARTID in
         let err : bool := true in
         returnm (err, ret))
       : M ((bool * mword 16))) >>= fun '((err, ret)
   : (bool * mword 16)) =>
   ((read_reg MPAMIDR_EL1_ref)  : M (mword 64)) >>= fun w__7 : mword 64 =>
   let partid_max := projT1 (uint (slice w__7 0 16)) in
   let '(err, ret) :=
     (if sumbool_of_bool (Z.gtb (projT1 (uint ret)) partid_max) then
        let ret : bits 16 := DefaultPARTID in
        let err : bool := true in
        (err, ret)
      else (err, ret))
      : (bool * mword 16) in
   returnm (ret, err).

