Definition Align__0 (x : Z) (y : Z) : Z := Z.mul y (projT1 (ediv_with_eq x y)).

Definition Align__1 {N : Z} (x : mword N) (y : Z) `{ArithFact (N >=? 0)} : mword N :=
   __GetSlice_int (length x) (Align__0 (projT1 (uint x)) y) 0.

Definition IsSecondStage (fault : FaultRecord) : M (bool) :=
   assert_exp (generic_neq fault.(FaultRecord_typ) Fault_None) "model/aarch_mem.sail 3434:34 - 3434:35" >>
   returnm fault.(FaultRecord_secondstage).

Definition IsFault (addrdesc : AddressDescriptor) : bool :=
   generic_neq addrdesc.(AddressDescriptor_fault).(FaultRecord_typ) Fault_None.

Definition CombineS1S2Desc (s1desc : AddressDescriptor) (s2desc : AddressDescriptor)
