      returnm result
    else if orb
              (generic_eq s2desc.(AddressDescriptor_memattrs).(MemoryAttributes_typ) MemType_Device)
              (generic_eq s1desc.(AddressDescriptor_memattrs).(MemoryAttributes_typ) MemType_Device)
    then
