      let __tc6 := {[ __tc6 with MemoryAttributes_typ := MemType_Normal ]}  : MemoryAttributes in
      let result := {[ result with AddressDescriptor_memattrs := __tc6 ]}  : AddressDescriptor in
      let __tc7 : MemoryAttributes := result.(AddressDescriptor_memattrs) in
      (undefined_DeviceType tt) >>= fun w__2 : DeviceType =>
      let __tc7 :=
