      let result := {[ result with AddressDescriptor_memattrs := __tc7 ]}  : AddressDescriptor in
      let __tc8 : MemoryAttributes := result.(AddressDescriptor_memattrs) in
      (CombineS1S2AttrHints s1desc.(AddressDescriptor_memattrs).(MemoryAttributes_inner)
         s2desc.(AddressDescriptor_memattrs).(MemoryAttributes_inner)) >>= fun w__3 : MemAttrHints =>
      let __tc8 := {[ __tc8 with MemoryAttributes_inner := w__3 ]}  : MemoryAttributes in
      let result := {[ result with AddressDescriptor_memattrs := __tc8 ]}  : AddressDescriptor in
