Definition TakeUnmaskedSErrorInterrupts '(tt : unit) : M (unit) :=
   (undefined_InterruptReq tt) >>= fun w__0 : InterruptReq =>
   let interrupt_req : InterruptReq := w__0  : InterruptReq in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_SE := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_vSE := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_FIQ := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_vFIQ := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_IRQ := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_vIRQ := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_iesb_req := false ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_SE := true ]} in
   let interrupt_req : InterruptReq := {[ interrupt_req with InterruptReq_take_vSE := true ]} in
   (TakePendingInterrupts interrupt_req) >>= fun interrupt_taken : bool => returnm tt.

