Definition TweakCellRot (incell_name : mword 4) : M (mword 4) :=
   (undefined_bitvector 4) >>= fun w__0 : mword 4 =>
   let outcell : bits 4 := w__0  : bits 4 in
   let outcell : bits 4 :=
     set_slice 4 1 outcell 3
       (xor_vec (vec_of_bits [access_vec_dec incell_name 0]  : mword 1)
          (vec_of_bits [access_vec_dec incell_name 1]  : mword 1)) in
   let outcell : bits 4 :=
     set_slice 4 1 outcell 2 (vec_of_bits [access_vec_dec incell_name 3]  : mword 1) in
   let outcell : bits 4 :=
     set_slice 4 1 outcell 1 (vec_of_bits [access_vec_dec incell_name 2]  : mword 1) in
   let outcell := set_slice 4 1 outcell 0 (vec_of_bits [access_vec_dec incell_name 1]  : mword 1) in
   returnm outcell.

