Definition DecodeShift (op : mword 2) : M (ShiftType) :=
   let b__0 := op in
   (if eq_vec b__0 ('b"00"  : mword 2) then returnm ShiftType_LSL
    else if eq_vec b__0 ('b"01"  : mword 2) then returnm ShiftType_LSR
    else if eq_vec b__0 ('b"10"  : mword 2) then returnm ShiftType_ASR
    else if eq_vec b__0 ('b"11"  : mword 2) then returnm ShiftType_ROR
    else
      assert_exp' false "Pattern match failure at model/aarch64.sail 2386:4 - 2399:5" >>= fun _ =>
      exit tt)
    : M (ShiftType).

Definition DecodeRegExtend (op : mword 3) : M (ExtendType) :=
   let b__0 := op in
   (if eq_vec b__0 ('b"000"  : mword 3) then returnm ExtendType_UXTB
    else if eq_vec b__0 ('b"001"  : mword 3) then returnm ExtendType_UXTH
    else if eq_vec b__0 ('b"010"  : mword 3) then returnm ExtendType_UXTW
    else if eq_vec b__0 ('b"011"  : mword 3) then returnm ExtendType_UXTX
    else if eq_vec b__0 ('b"100"  : mword 3) then returnm ExtendType_SXTB
    else if eq_vec b__0 ('b"101"  : mword 3) then returnm ExtendType_SXTH
    else if eq_vec b__0 ('b"110"  : mword 3) then returnm ExtendType_SXTW
    else if eq_vec b__0 ('b"111"  : mword 3) then returnm ExtendType_SXTX
    else
      assert_exp' false "Pattern match failure at model/aarch64.sail 2405:4 - 2430:5" >>= fun _ =>
      exit tt)
    : M (ExtendType).

