Definition DataSynchronizationBarrier (domain : MBReqDomain) (types : MBReqTypes) : unit := tt.

Definition DataMemoryBarrier (domain : MBReqDomain) (types : MBReqTypes) : unit := tt.

Definition system_barriers (domain : MBReqDomain) (op : MemBarrierOp) (types : MBReqTypes) : unit :=
   match op with
   | MemBarrierOp_DSB => DataSynchronizationBarrier domain types
   | MemBarrierOp_DMB => DataMemoryBarrier domain types
   | MemBarrierOp_ISB => InstructionSynchronizationBarrier tt
   | MemBarrierOp_SSBB => SpeculativeSynchronizationBarrierToVA tt
   | MemBarrierOp_PSSBB => SpeculativeSynchronizationBarrierToPA tt
   | MemBarrierOp_SB => SpeculationBarrier tt
   end.

