   assert_exp' (orb (Z.eqb (projT1 (__id width)) 8)
                  (orb (Z.eqb (projT1 (__id width)) 16)
                     (orb (Z.eqb (projT1 (__id width)) 32) (Z.eqb (projT1 (__id width)) 64)))) "model/aarch64.sail 3028:67 - 3028:68" >>= fun _ =>
   read_reg PSTATE_ref >>= fun w__0 : ProcState =>
   (if eq_vec w__0.(ProcState_SP) ('b"0"  : mword 1) then
