      returnm (slice w__1 0 (projT1 (__id width)))
    else
      read_reg PSTATE_ref >>= fun w__2 : ProcState =>
      let p__554 := w__2.(ProcState_EL) in
      let _pat_ := p__554 in
      (if eq_vec _pat_ EL0 then
         ((read_reg SP_EL0_ref)  : M (mword 64)) >>= fun w__3 : mword 64 =>
         returnm (slice w__3 0 (projT1 (__id width)))
       else if eq_vec _pat_ EL1 then
         ((read_reg SP_EL1_ref)  : M (mword 64)) >>= fun w__4 : mword 64 =>
         returnm (slice w__4 0 (projT1 (__id width)))
       else if eq_vec _pat_ EL2 then
         ((read_reg SP_EL2_ref)  : M (mword 64)) >>= fun w__5 : mword 64 =>
         returnm (slice w__5 0 (projT1 (__id width)))
       else if eq_vec _pat_ EL3 then
         ((read_reg SP_EL3_ref)  : M (mword 64)) >>= fun w__6 : mword 64 =>
         returnm (slice w__6 0 (projT1 (__id width)))
       else
         assert_exp' false "Pattern match failure at model/aarch64.sail 3032:8 - 3045:9" >>= fun _ =>
