Definition PARAttrsDecode (memattrs : MemoryAttributes) : M (mword 8) :=
   (undefined_bitvector 8) >>= fun w__0 : mword 8 =>
   let result : bits 8 := w__0  : bits 8 in
   let result : mword 8 :=
     if generic_eq memattrs.(MemoryAttributes_typ) MemType_Device then
       let result : bits 8 := set_slice 8 4 result 4 (Ox"0"  : mword 4) in
       if generic_eq memattrs.(MemoryAttributes_device) DeviceType_nGnRnE then
         set_slice 8 4 result 0 (Ox"0"  : mword 4)
       else if generic_eq memattrs.(MemoryAttributes_device) DeviceType_nGnRE then
         set_slice 8 4 result 0 (Ox"4"  : mword 4)
       else if generic_eq memattrs.(MemoryAttributes_device) DeviceType_nGRE then
         set_slice 8 4 result 0 (Ox"8"  : mword 4)
       else set_slice 8 4 result 0 (Ox"C"  : mword 4)
     else
       let result : mword 8 :=
         if eq_vec memattrs.(MemoryAttributes_outer).(MemAttrHints_attrs) MemAttr_WT then
           let result : bits 8 :=
             set_slice 8 2 result 6
               (if memattrs.(MemoryAttributes_outer).(MemAttrHints_transient) then 'b"00"  : mword 2
                else 'b"10"  : mword 2) in
           set_slice 8 2 result 4 memattrs.(MemoryAttributes_outer).(MemAttrHints_hints)
         else if eq_vec memattrs.(MemoryAttributes_outer).(MemAttrHints_attrs) MemAttr_WB then
           let result : bits 8 :=
             set_slice 8 2 result 6
               (if memattrs.(MemoryAttributes_outer).(MemAttrHints_transient) then 'b"01"  : mword 2
                else 'b"11"  : mword 2) in
           set_slice 8 2 result 4 memattrs.(MemoryAttributes_outer).(MemAttrHints_hints)
         else set_slice 8 4 result 4 (Ox"4"  : mword 4) in
       if eq_vec memattrs.(MemoryAttributes_inner).(MemAttrHints_attrs) MemAttr_WT then
         let result : bits 8 :=
           set_slice 8 2 result 2
             (if memattrs.(MemoryAttributes_inner).(MemAttrHints_transient) then 'b"00"  : mword 2
              else 'b"10"  : mword 2) in
         set_slice 8 2 result 0 memattrs.(MemoryAttributes_inner).(MemAttrHints_hints)
       else if eq_vec memattrs.(MemoryAttributes_inner).(MemAttrHints_attrs) MemAttr_WB then
         let result : bits 8 :=
