Definition HighestSetBit {N : Z} (x : mword N) `{ArithFact (N >=? 0)}
: M ({n : Z & ArithFact ((-1 <=? n) && (n <=? (N - 1)))}) :=
   catch_early_return
     ((let loop_i_lower := 0 in
     let loop_i_upper := Z.sub (length x) 1 in
     (foreach_ZM_down loop_i_upper loop_i_lower 1 tt
       (fun i _ _ =>
         (if eq_vec (vec_of_bits [access_vec_dec x i]  : mword 1) ('b"1"  : mword 1) then
            (early_return (build_ex
            (projT1
            (build_ex
            i
             : {n : Z & ArithFact ((-1 <=? n) && (n <=? (N - 1)))}))) :
              MR unit {n : Z & ArithFact ((-1 <=? n) && (n <=? (N - 1)))})
             : MR (unit) _
          else returnm tt)
          : MR (unit) _))) >>
     returnm (build_ex (Z.opp 1))).

