          (append_int
             (String.append
                (String.append
                   (String.append
                      (String.append (String.append "Prefetch" " address=0x")
                         (hex_str (projT1 (uint address)))) " op=") op) " target=") target)
          " stream=") stream in
   let '_ := (__tarmacEvent msg)  : unit in
   returnm tt.

Definition NextInstrAddr (N : Z) `{ArithFact ((0 <=? N) && (N <=? 64))} : M (mword N) :=
   ((read_reg _PC_ref)  : M (mword 64)) >>= fun w__0 : mword 64 =>
   read_reg __currentInstrLength_ref >>= fun w__1 : Z => returnm (slice (add_vec_int w__0 w__1) 0 N).

Definition CountLeadingZeroBits {N : Z} (x : mword N) `{ArithFact (N >=? 0)} : M (Z) :=
   (HighestSetBit x) >>= fun '(existT _ w__0 _ : {n : Z & ArithFact ((-1 <=? n) && (n <=? (N - 1)))}) =>
   returnm (Z.sub (length x) (Z.add w__0 1)).

Definition CountLeadingSignBits {N : Z} (x : mword N) `{ArithFact (N >=? 1)} : M (Z) :=
   (CountLeadingZeroBits (xor_vec (slice x 1 (Z.sub (length x) 1)) (slice x 0 (Z.sub (length x) 1))))
    : M (Z).

Definition RotCell (incell_name : mword 4) (amount : Z) : M (mword 4) :=
   (undefined_bitvector 8) >>= fun w__0 : mword 8 =>
   let tmp : bits 8 := w__0  : bits 8 in
   (undefined_bitvector 4) >>= fun w__1 : mword 4 =>
   let outcell : bits 4 := w__1  : bits 4 in
   let tmp := set_slice 8 8 tmp 0 (concat_vec (slice incell_name 0 4) (slice incell_name 0 4)) in
   let outcell := slice tmp (Z.sub 4 amount) 4 in
   returnm outcell.

Definition ProcessorID '(tt : unit) : M (Z) :=
   ((read_reg MPIDR_EL1_ref)  : M (mword 64)) >>= fun w__0 : mword 64 =>
   ((read_reg MPIDR_EL1_ref)  : M (mword 64)) >>= fun w__1 : mword 64 =>
   ((read_reg MPIDR_EL1_ref)  : M (mword 64)) >>= fun w__2 : mword 64 =>
   ((read_reg MPIDR_EL1_ref)  : M (mword 64)) >>= fun w__3 : mword 64 =>
   returnm (projT1
            (uint
               (concat_vec
                  (concat_vec (concat_vec (slice w__0 32 8) (slice w__1 16 8)) (slice w__2 8 8))
                  (slice w__3 0 8)))).

Definition system_monitors '(tt : unit) : M (unit) :=
   (ProcessorID tt) >>= fun w__0 : Z => (ClearExclusiveLocal w__0)  : M (unit).

Definition NextRandomTagBit '(tt : unit) : M (mword 1) :=
   ((read_reg RGSR_EL1_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
   let lfsr := slice w__0 8 16 in
   let top : bits 1 :=
     xor_vec
       (xor_vec
          (xor_vec (vec_of_bits [access_vec_dec lfsr 5]  : mword 1)
             (vec_of_bits [access_vec_dec lfsr 3]  : mword 1))
          (vec_of_bits [access_vec_dec lfsr 2]  : mword 1))
       (vec_of_bits [access_vec_dec lfsr 0]  : mword 1) in
   ((read_reg RGSR_EL1_ref)  : M (mword 32)) >>= fun w__1 : mword 32 =>
   write_reg RGSR_EL1_ref (set_slice 32 16 w__1 8 (concat_vec top (slice lfsr 1 15))) >> returnm top.

Definition RandomTag '(tt : unit) : M (mword 4) :=
   (undefined_bitvector 4) >>= fun w__0 : mword 4 =>
   let tag : bits 4 := w__0  : bits 4 in
   (let loop_i_lower := 0 in
   let loop_i_upper := 3 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 tag
     (fun i _ tag =>
       (NextRandomTagBit tt) >>= fun w__1 : mword 1 =>
       let tag : bits 4 := set_slice 4 1 tag i w__1 in
       returnm tag)))
    : M (mword 4).

Definition MakeLSInstructionSyndrome
(size : Z) (sign_extend : bool) (Rt : Z) (sixty_four : bool) (acq_rel : bool)
`{ArithFact (member_Z_list size [1; 2; 4; 8] && ((0 <=? Rt) && (Rt <=? 31)))}
: M (mword 11) :=
   assert_exp' (orb (Z.eqb size 1) (orb (Z.eqb size 2) (orb (Z.eqb size 4) (Z.eqb size 8)))) "model/aarch64.sail 3393:56 - 3393:57" >>= fun _ =>
   assert_exp' (andb (Z.leb 0 Rt) (Z.leb Rt 31)) "model/aarch64.sail 3394:29 - 3394:30" >>= fun _ =>
   (undefined_bitvector 2) >>= fun w__0 : mword 2 =>
   let sz : bits 2 := w__0  : bits 2 in
   let l__147 := size in
   (if sumbool_of_bool (Z.eqb l__147 1) then
      let sz : bits 2 := 'b"00"  : mword 2 in
      returnm sz
    else if sumbool_of_bool (Z.eqb l__147 2) then
      let sz : bits 2 := 'b"01"  : mword 2 in
      returnm sz
    else if sumbool_of_bool (Z.eqb l__147 4) then
      let sz : bits 2 := 'b"10"  : mword 2 in
      returnm sz
    else if sumbool_of_bool (Z.eqb l__147 8) then
      let sz : bits 2 := 'b"11"  : mword 2 in
      returnm sz
    else
      assert_exp' false "Pattern match failure at model/aarch64.sail 3396:4 - 3409:5" >>= fun _ =>
      exit tt) >>= fun sz : mword 2 =>
   let sz := sz in
   let ext := if sumbool_of_bool sign_extend then 'b"1"  : mword 1 else 'b"0"  : mword 1 in
   let sf := if sumbool_of_bool sixty_four then 'b"1"  : mword 1 else 'b"0"  : mword 1 in
   let ar := if sumbool_of_bool acq_rel then 'b"1"  : mword 1 else 'b"0"  : mword 1 in
   returnm (concat_vec
              (concat_vec
                 (concat_vec (concat_vec (concat_vec ('b"1"  : mword 1) sz) ext)
                    (__GetSlice_int 5 Rt 0)) sf) ar).

Definition AArch64_SetLSInstructionSyndrome
(size : Z) (sign_extend : bool) (Rt : Z) (sixty_four : bool) (acq_rel : bool)
`{ArithFact (member_Z_list size [1; 2; 4; 8] && ((0 <=? Rt) && (Rt <=? 31)))}
: M (unit) :=
   (or_boolM
      (read_reg PSTATE_ref >>= fun w__0 : ProcState =>
       returnm ((eq_vec w__0.(ProcState_EL) EL0)  : bool))
      (read_reg PSTATE_ref >>= fun w__1 : ProcState =>
       returnm ((eq_vec w__1.(ProcState_EL) EL1)  : bool))) >>= fun w__2 : bool =>
   (if sumbool_of_bool w__2 then
      (MakeLSInstructionSyndrome size sign_extend Rt sixty_four acq_rel) >>= fun w__3 : mword 11 =>
      write_reg __LSISyndrome_ref w__3
       : M (unit)
    else returnm tt)
    : M (unit).

Definition AArch64_PARFaultStatus (fault : FaultRecord) : M (mword 6) :=
   (undefined_bitvector 6) >>= fun w__0 : mword 6 =>
   let fst : bits 6 := w__0  : bits 6 in
   (if generic_eq fault.(FaultRecord_typ) Fault_Domain then
      assert_exp (orb (Z.eqb fault.(FaultRecord_level) 1) (Z.eqb fault.(FaultRecord_level) 2)) "model/aarch64.sail 3432:50 - 3432:51" >>
      let fst : bits 6 :=
        set_slice 6 2 fst 0
          (if Z.eqb fault.(FaultRecord_level) 1 then 'b"01"  : mword 2
           else 'b"10"  : mword 2) in
      let fst : bits 6 := set_slice 6 4 fst 2 (Ox"F"  : mword 4) in
      returnm fst
    else (EncodeLDFSC fault.(FaultRecord_typ) fault.(FaultRecord_level))  : M (mword 6))
    : M (mword 6).

Definition AllocationTagFromAddress (tagged_address : mword 64) : mword 4 :=
   let logical_tag : bits 4 := slice tagged_address 56 4 in
   add_vec logical_tag
     (concat_vec ('b"000"  : mword 3) (vec_of_bits [access_vec_dec tagged_address 55]  : mword 1)).

Definition AddressWithAllocationTag (address : mword 64) (allocation_tag : mword 4) : mword 64 :=
   let result : bits 64 := address in
   let tag :=
     sub_vec allocation_tag
       (concat_vec ('b"000"  : mword 3) (vec_of_bits [access_vec_dec address 55]  : mword 1)) in
   set_slice 64 4 result 56 tag.

Definition aset_Elem__1 {N : Z} (vector_name : mword N) (e : Z) (size : Z) (value_name : mword size)
`{ArithFact ((N >=? 0) && (size >=? 0))}
: M (mword N) :=
   assert_exp' (andb (Z.geb e 0) (Z.leb (Z.mul (Z.add e 1) size) (length vector_name))) "model/aarch64.sail 3476:40 - 3476:41" >>= fun _ =>
   let vector_name := set_slice (length vector_name) size vector_name (Z.mul e size) value_name in
   returnm vector_name.

