Definition TLBReset '(tt : unit) : M (unit) :=
   read_reg TLBHits_ref >>= fun w__0 : Z =>
   read_reg TLBMisses_ref >>= fun w__1 : Z =>
   (if sumbool_of_bool (Z.gtb (Z.add w__0 w__1) 0) then
      let '_ := (prerr "TLB reset, so far hit rate is ")  : unit in
      read_reg TLBHits_ref >>= fun w__2 : Z =>
      let '_ := (asl_prerr_int w__2)  : unit in
      let '_ := (prerr "/")  : unit in
      read_reg TLBHits_ref >>= fun w__3 : Z =>
      read_reg TLBMisses_ref >>= fun w__4 : Z =>
      let '_ := (asl_prerr_int (Z.add w__3 w__4))  : unit in
      let '_ := (prerr " == ")  : unit in
      read_reg TLBHits_ref >>= fun w__5 : Z =>
      read_reg TLBHits_ref >>= fun w__6 : Z =>
      read_reg TLBMisses_ref >>= fun w__7 : Z =>
      let '_ := (asl_prerr_int (projT1 (ediv_with_eq (Z.mul 100 w__5) (Z.add w__6 w__7))))  : unit in
      returnm (println tt)
    else
      let '_ := (prerr "TLB reset (no requests were made)")  : unit in
      returnm (println tt)) >>
   write_reg TLBHits_ref 0 >>
   write_reg TLBMisses_ref 0 >>
   let loop_i_lower := 0 in
   let loop_i_upper := Z.sub (shl_int 1 10) 1 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 tt
     (fun i _ _ =>
       read_reg _TLB_ref >>= fun w__8 : vec TLBLine 1024 =>
       let __tc1 : TLBLine := vector_access_B w__8 i in
       let __tc1 := {[ __tc1 with TLBLine_valid_name := false ]}  : TLBLine in
       read_reg _TLB_ref >>= fun w__9 : vec TLBLine 1024 =>
       write_reg _TLB_ref (vec_update_dec_loose w__9 i __tc1)
        : M (unit))).

