Definition aset_V {width : Z} (n : Z) (value_name : mword width)
`{ArithFact ((n >=? 0) && (n <=? 31))}
: M (unit) :=
   assert_exp' (orb (Z.eqb (length value_name) 8)
                  (orb (Z.eqb (length value_name) 16)
                     (orb (Z.eqb (length value_name) 32)
                        (orb (Z.eqb (length value_name) 64) (Z.eqb (length value_name) 128))))) "model/aarch64.sail 3904:83 - 3904:84" >>= fun _ =>
   read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
   (ZeroExtend__0 value_name 128) >>= fun w__1 : mword 128 =>
   write_reg _V_ref (vec_update_dec_loose w__0 n w__1)
    : M (unit).

Definition AArch64_ResetSIMDFPRegisters '(tt : unit) : M (unit) :=
   let loop_i_lower := 0 in
   let loop_i_upper := 31 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 tt
     (fun i _ _ =>
       (undefined_bitvector 128) >>= fun w__0 : mword 128 =>
       (aset_V i (w__0  : bits 128))
        : M (unit))).

Definition aset_SP {width : Z} (value_name : mword width) `{ArithFact (width >=? 0)} : M (unit) :=
   assert_exp' (orb (Z.eqb (length value_name) 32) (Z.eqb (length value_name) 64)) "model/aarch64.sail 3923:38 - 3923:39" >>= fun _ =>
   read_reg PSTATE_ref >>= fun w__0 : ProcState =>
   (if eq_vec w__0.(ProcState_SP) ('b"0"  : mword 1) then
      (ZeroExtend__1 64 value_name) >>= fun w__1 : mword 64 => write_reg SP_EL0_ref w__1  : M (unit)
    else
      read_reg PSTATE_ref >>= fun w__2 : ProcState =>
      let p__553 := w__2.(ProcState_EL) in
      let _pat_ := p__553 in
      (if eq_vec _pat_ EL0 then
         (ZeroExtend__1 64 value_name) >>= fun w__3 : mword 64 =>
         write_reg SP_EL0_ref w__3
          : M (unit)
       else if eq_vec _pat_ EL1 then
         (ZeroExtend__1 64 value_name) >>= fun w__4 : mword 64 =>
         write_reg SP_EL1_ref w__4
          : M (unit)
       else if eq_vec _pat_ EL2 then
         (ZeroExtend__1 64 value_name) >>= fun w__5 : mword 64 =>
         write_reg SP_EL2_ref w__5
          : M (unit)
       else if eq_vec _pat_ EL3 then
         (ZeroExtend__1 64 value_name) >>= fun w__6 : mword 64 =>
         write_reg SP_EL3_ref w__6
          : M (unit)
       else
         assert_exp' false "Pattern match failure at model/aarch64.sail 3927:8 - 3940:9" >>= fun _ =>
         exit tt)
       : M (unit))
    : M (unit).

Definition aset__MemTag (desc : AddressDescriptor) (value_name : mword 4) : M (unit) :=
   (ZeroExtend__1 64 desc.(AddressDescriptor_paddress).(FullAddress_address)) >>= fun offset : bits 64 =>
   let log2_tag_granule := LOG2_TAG_GRANULE in
   assert_exp' (Z.geb log2_tag_granule 0) "model/aarch64.sail 3952:32 - 3952:33" >>= fun _ =>
   (LSR offset log2_tag_granule) >>= fun tag_index : bits 64 =>
   let tagaddress : bits 56 := add_vec TAG_STORE_AREA (slice tag_index 0 56) in
   (ZeroExtend__1 56 tagaddress) >>= fun w__0 : mword 56 =>
   (__WriteMemory 1 w__0 (concat_vec (Ox"0"  : mword 4) value_name))
    : M (unit).

Definition Poly32Mod2 {N : Z} (data__arg : mword N) (poly : mword 32) `{ArithFact (N >=? 0)}
: M (mword 32) :=
   let data := data__arg in
   assert_exp' (Z.gtb (length data__arg) 32) "model/aarch64.sail 3965:18 - 3965:19" >>= fun _ =>
   let data : mword N :=
     let loop_i_lower := 32 in
     let loop_i_upper := Z.sub (length data__arg) 1 in
     (foreach_Z_down loop_i_upper loop_i_lower 1 data
       (fun i _ data =>
         if eq_vec (vec_of_bits [access_vec_dec data i]  : mword 1) ('b"1"  : mword 1) then
           set_slice (length data__arg) i data 0
             (xor_vec (slice data 0 i) (autocast (autocast (concat_vec poly (zeros (Z.sub i 32))))))
         else data)) in
   returnm (slice data 0 32).

Definition LSL_C {N : Z} (x : mword N) (shift : Z) `{ArithFact (N >=? 0)} : M ((mword N * mword 1)) :=
   assert_exp' (Z.gtb shift 0) "model/aarch64.sail 3978:20 - 3978:21" >>= fun _ =>
   let shift := if sumbool_of_bool (Z.gtb shift (length x)) then length x else shift in
   let extended_x : bits (N + shift) := concat_vec x (zeros shift) in
   let result : bits N := slice extended_x 0 (length x) in
   let carry_out : bits 1 := (vec_of_bits [access_vec_dec extended_x (length x)]  : mword 1) in
   returnm (result, carry_out).

Definition LSL {N : Z} (x : mword N) (shift : Z) `{ArithFact ((shift >=? 0) && (N >=? 0))}
: M (mword N) :=
   assert_exp' (Z.geb shift 0) "model/aarch64.sail 3990:21 - 3990:22" >>= fun _ =>
   (undefined_bitvector 1) >>= fun w__0 : mword 1 =>
   let __anon1 : bits 1 := w__0  : bits 1 in
   (undefined_bitvector (length x)) >>= fun w__1 : mword N =>
   let result : bits N := w__1  : bits N in
   (if sumbool_of_bool (Z.eqb shift 0) then returnm x
    else
