: (mword N * mword 4) :=
   let unsigned_sum := Z.add (Z.add (projT1 (uint x)) (projT1 (uint y))) (projT1 (uint carry_in)) in
   let signed_sum := Z.add (Z.add (sint_plain x) (sint_plain y)) (projT1 (uint carry_in)) in
