Definition DecodeBitMasks
(M' : Z) (immN : mword 1) (imms : mword 6) (immr : mword 6) (immediate : bool)
`{ArithFact (M' >=? 0)}
: M ((mword M' * mword M')) :=
   (undefined_bitvector 64) >>= fun w__0 : mword 64 =>
   let tmask : bits 64 := w__0  : bits 64 in
   (undefined_bitvector 64) >>= fun w__1 : mword 64 =>
   let wmask : bits 64 := w__1  : bits 64 in
   (undefined_bitvector 6) >>= fun w__2 : mword 6 =>
   let tmask_and : bits 6 := w__2  : bits 6 in
   (undefined_bitvector 6) >>= fun w__3 : mword 6 =>
   let wmask_and : bits 6 := w__3  : bits 6 in
   (undefined_bitvector 6) >>= fun w__4 : mword 6 =>
   let tmask_or : bits 6 := w__4  : bits 6 in
   (undefined_bitvector 6) >>= fun w__5 : mword 6 =>
   let wmask_or : bits 6 := w__5  : bits 6 in
   (undefined_bitvector 6) >>= fun w__6 : mword 6 =>
   let levels : bits 6 := w__6  : bits 6 in
   (projT1_m
    (HighestSetBit (concat_vec immN (not_vec imms)))) >>= fun len : Z =>
   (match sumbool_of_bool  (Z.ltb len 1) with
   | left _ => throw (Error_Undefined tt)
   | right _non_throw_hyp => returnm _non_throw_hyp
   end)
    >>= fun _ => 
   assert_exp' (Z.geb len 1) "model/aarch64.sail 7867:19 - 7867:20" >>= fun _ =>
   assert_exp (Z.geb (projT1 (__id M')) (shl_int 1 len)) "model/aarch64.sail 7868:32 - 7868:33" >>
   (ZeroExtend__0 (Ones len) 6) >>= fun levels =>
   (match sumbool_of_bool  (andb immediate (eq_vec (and_vec imms levels) levels)) with
   | left _ => throw (Error_Undefined tt)
   | right _non_throw_hyp => returnm _non_throw_hyp
   end)
    >>= fun _ => 
   let S' : Z := projT1 (uint (and_vec imms levels)) in
   let R : Z := projT1 (uint (and_vec immr levels)) in
   let diff : Z := Z.sub S' R in
   let tmask_and := or_vec (__GetSlice_int 6 diff 0) (not_vec levels) in
   let tmask_or := and_vec (__GetSlice_int 6 diff 0) levels in
   let tmask : bits 64 := Ones 64 in
   let tmask : bits 64 :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 0]  : mword 1) 1)
                (Ones 1)) 32))
       (replicate_bits
          (concat_vec (zeros 1)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 0]  : mword 1) 1)) 32) in
   let tmask : bits 64 :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 1]  : mword 1) 2)
                (Ones 2)) 16))
       (replicate_bits
          (concat_vec (zeros 2)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 1]  : mword 1) 2)) 16) in
   let tmask : bits 64 :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 2]  : mword 1) 4)
                (Ones 4)) 8))
       (replicate_bits
          (concat_vec (zeros 4)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 2]  : mword 1) 4)) 8) in
   let tmask : bits 64 :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 3]  : mword 1) 8)
                (Ones 8)) 4))
       (replicate_bits
          (concat_vec (zeros 8)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 3]  : mword 1) 8)) 4) in
   let tmask : bits 64 :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 4]  : mword 1) 16)
                (Ones 16)) 2))
       (replicate_bits
          (concat_vec (zeros 16)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 4]  : mword 1) 16)) 2) in
   let tmask :=
     or_vec
       (and_vec tmask
          (replicate_bits
             (concat_vec (replicate_bits (vec_of_bits [access_vec_dec tmask_and 5]  : mword 1) 32)
                (Ones 32)) 1))
       (replicate_bits
          (concat_vec (zeros 32)
             (replicate_bits (vec_of_bits [access_vec_dec tmask_or 5]  : mword 1) 32)) 1) in
   let wmask_and := or_vec immr (not_vec levels) in
   let wmask_or := and_vec immr levels in
   let wmask : bits 64 := zeros 64 in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 1)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 0]  : mword 1) 1)) 32))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 0]  : mword 1) 1)
             (zeros 1)) 32) in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 2)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 1]  : mword 1) 2)) 16))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 1]  : mword 1) 2)
             (zeros 2)) 16) in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 4)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 2]  : mword 1) 4)) 8))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 2]  : mword 1) 4)
             (zeros 4)) 8) in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 8)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 3]  : mword 1) 8)) 4))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 3]  : mword 1) 8)
             (zeros 8)) 4) in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 16)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 4]  : mword 1) 16)) 2))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 4]  : mword 1) 16)
             (zeros 16)) 2) in
   let wmask : bits 64 :=
     or_vec
       (and_vec wmask
          (replicate_bits
             (concat_vec (Ones 32)
                (replicate_bits (vec_of_bits [access_vec_dec wmask_and 5]  : mword 1) 32)) 1))
       (replicate_bits
          (concat_vec (replicate_bits (vec_of_bits [access_vec_dec wmask_or 5]  : mword 1) 32)
             (zeros 32)) 1) in
   let wmask : mword 64 :=
     if neq_vec (__GetSlice_int 1 diff 6) ('b"0"  : mword 1) then and_vec wmask tmask
     else or_vec wmask tmask in
   returnm (slice wmask 0 (projT1 (__id M')), slice tmask 0 (projT1 (__id M'))).

Definition ChooseNonExcludedTag (tag__arg : mword 4) (offset__arg : mword 4) (exclude : mword 16)
: M (mword 4) :=
   let offset := offset__arg in
   let tag := tag__arg in
   (if eq_vec exclude (Ones 16) then returnm tag
    else
      (whileMT
        (offset, tag)
        (fun '(offset, tag) => projT1 (uint offset))
        (fun '(offset, tag) => returnm (neq_vec offset (Ox"0"  : mword 4)))
        (fun '(offset, tag) =>
          let offset := (sub_vec offset (Ox"1"  : mword 4))  : mword 4 in
          let tag := (add_vec tag (Ox"1"  : mword 4))  : mword 4 in
          (whileMT
            tag
            (fun tag => 16)
            (fun tag =>
              returnm (eq_vec (vec_of_bits [access_vec_dec exclude (projT1 (uint tag))]  : mword 1)
                         ('b"1"
                          : mword 1)))
            (fun tag =>
              let tag : mword 4 := add_vec tag (Ox"1"  : mword 4) in
              returnm tag)) >>= fun tag : mword 4 =>
          returnm (offset, tag))) >>= fun '((offset, tag)
      : (mword 4 * mword 4)) =>
      returnm tag)
    : M (mword 4).

Definition BTypeCompatible_BTI (hintcode : mword 2) : M (bool) :=
   let b__0 := hintcode in
   (if eq_vec b__0 ('b"00"  : mword 2) then returnm false
    else if eq_vec b__0 ('b"01"  : mword 2) then
      read_reg PSTATE_ref >>= fun w__0 : ProcState =>
      returnm (neq_vec w__0.(ProcState_BTYPE) ('b"11"  : mword 2))
    else if eq_vec b__0 ('b"10"  : mword 2) then
      read_reg PSTATE_ref >>= fun w__1 : ProcState =>
      returnm (neq_vec w__1.(ProcState_BTYPE) ('b"10"  : mword 2))
    else if eq_vec b__0 ('b"11"  : mword 2) then returnm true
    else
      assert_exp' false "Pattern match failure at model/aarch64.sail 7923:4 - 7936:5" >>= fun _ =>
      exit tt)
    : M (bool).

Definition integer_tags_mcsubtag
