          : (mword 64 * mword 4) in
       let result : bits 64 := tup__0 in
       let __anon1 : bits 4 := tup__1 in
       result
     else
       let '(tup__0, tup__1) :=
         (AddWithCarry operand1 (not_vec offset) ('b"1"  : mword 1))
          : (mword 64 * mword 4) in
       let result : bits 64 := tup__0 in
       let __anon2 : bits 4 := tup__1 in
