Definition ResetControlRegisters (cold : bool) : M (unit) :=
   (HighestELUsingAArch32 tt) >>= fun w__0 : bool =>
   (if sumbool_of_bool (negb w__0) then (AArch64_AutoGen_ArchitectureReset cold)  : M (unit)
    else (AArch32_AutoGen_ArchitectureReset cold)  : M (unit)) >>
   (AArch32_IMPDEFResets tt) >> (AArch64_IMPDEFResets tt) >> (__Reset cold)  : M (unit).

Definition AArch64_ResetControlRegisters (cold_reset : bool) : M (unit) :=
   (ResetControlRegisters cold_reset) >> (_TLB_Invalidate tt)  : M (unit).

