   write_reg PSTATE_ref {[ w__0 with ProcState_SS := ('b"0"  : mword 1) ]} >>
   (ResetControlRegisters cold_reset) >> (_TLB_Invalidate tt)  : M (unit).

Definition AArch64_ExecutingBTIInstr '(tt : unit) : M (bool) :=
   (if negb (HaveBTIExt tt) then returnm false
    else
      (ThisInstr tt) >>= fun instr =>
      (undefined_bitvector 4) >>= fun w__0 : mword 4 =>
      let CRm : bits 4 := w__0  : bits 4 in
      (undefined_bitvector 3) >>= fun w__1 : mword 3 =>
      let op2 : bits 3 := w__1  : bits 3 in
      let w__2 : bool :=
        if andb
             (andb (eq_vec (slice instr 22 10) ('b"1101010100"  : mword 10))
                (eq_vec (slice instr 12 10) ('b"0000110010"  : mword 10)))
             (eq_vec (slice instr 0 5) ('b"11111"  : mword 5)) then
          let CRm : bits 4 := slice instr 8 4 in
          let op2 : bits 3 := slice instr 5 3 in
          andb (eq_vec CRm (Ox"4"  : mword 4))
            (eq_vec (vec_of_bits [access_vec_dec op2 0]  : mword 1) ('b"0"  : mword 1))
        else false in
      returnm w__2)
    : M (bool).

Definition AArch64_ExecutingBROrBLROrRetInstr '(tt : unit) : M (bool) :=
   (if negb (HaveBTIExt tt) then returnm false
    else
      (ThisInstr tt) >>= fun instr =>
      (undefined_bitvector 4) >>= fun w__0 : mword 4 =>
      let opc : bits 4 := w__0  : bits 4 in
      let w__1 : bool :=
        if andb (eq_vec (slice instr 25 7) ('b"1101011"  : mword 7))
             (eq_vec (slice instr 16 5) ('b"11111"  : mword 5)) then
          let opc : bits 4 := slice instr 21 4 in
          neq_vec opc (Ox"5"  : mword 4)
        else false in
      returnm w__1)
    : M (bool).

Definition AArch64_EncodePAR (addrdesc : AddressDescriptor) : M (unit) :=
   (undefined_bitvector 64) >>= fun w__0 : mword 64 =>
   let par : bits 64 := w__0  : bits 64 in
   let par := (__GetSlice_int 64 2048 0)  : mword 64 in
   (if negb (IsFault addrdesc) then
