      (PARShareabilityDecode addrdesc.(AddressDescriptor_memattrs)) >>= fun w__1 : mword 2 =>
      let par := (set_slice 64 2 par 7 w__1)  : mword 64 in
      let par :=
        (set_slice 64 1 par 9 addrdesc.(AddressDescriptor_paddress).(FullAddress_NS))
         : mword 64 in
      let par :=
