           (slice addrdesc.(AddressDescriptor_paddress).(FullAddress_address) 12 40))
         : mword 64 in
      (PARAttrsDecode addrdesc.(AddressDescriptor_memattrs)) >>= fun w__2 : mword 8 =>
      let par : bits 64 := set_slice 64 8 par 56 w__2 in
      returnm par
    else
      let par := (set_slice 64 1 par 0 ('b"1"  : mword 1))  : mword 64 in
      (AArch64_PARFaultStatus addrdesc.(AddressDescriptor_fault)) >>= fun w__3 : mword 6 =>
      let par : bits 64 := set_slice 64 6 par 1 w__3 in
      let par : bits 64 :=
        set_slice 64 1 par 8
          (if addrdesc.(AddressDescriptor_fault).(FaultRecord_s2fs1walk) then 'b"1"  : mword 1
           else 'b"0"  : mword 1) in
      let par : bits 64 :=
        set_slice 64 1 par 9
          (if addrdesc.(AddressDescriptor_fault).(FaultRecord_secondstage) then 'b"1"  : mword 1
           else 'b"0"  : mword 1) in
      returnm par) >>= fun par : mword 64 =>
   ((read_reg PAR_EL1_ref)  : M (mword 64)) >>= fun w__4 : mword 64 =>
   write_reg PAR_EL1_ref (set_slice 64 64 w__4 0 par)
    : M (unit).

Definition AArch64_ESBOperation '(tt : unit) : M (unit) :=
