      (((read_reg SCR_EL3_ref)  : M (mword 32)) >>= fun w__1 : mword 32 =>
       returnm ((eq_vec (vec_of_bits [access_vec_dec w__1 3]  : mword 1) ('b"1"  : mword 1))
        : bool))) >>= fun route_to_el3 =>
