Definition AArch64_SysInstr (op0 : Z) (op1 : Z) (crn : Z) (crm : Z) (op2 : Z) (val_name : mword 64)
: M (unit) :=
   read_reg PSTATE_ref >>= fun w__0 : ProcState =>
   (AArch64_AutoGen_SysOpsWrite w__0.(ProcState_EL) (__GetSlice_int 2 op0 0)
      (__GetSlice_int 3 op1 0) (__GetSlice_int 4 crn 0) (__GetSlice_int 3 op2 0)
      (__GetSlice_int 4 crm 0) ('b"0"  : mword 1) val_name)
    : M (unit).

Definition system_sysops
(has_result : bool) (sys_crm : Z) (sys_crn : Z) (sys_op0 : Z) (sys_op1 : Z) (sys_op2 : Z) (t : Z)
`{ArithFact (((t >=? 0) && (t <=? 31) || negb has_result) &&
  ((t >=? 0) && (t <=? 31) || negb (negb has_result)))}
: M (unit) :=
   (if sumbool_of_bool has_result then
      (AArch64_SysInstrWithResult sys_op0 sys_op1 sys_crn sys_crm sys_op2) >>= fun w__0 : mword 64 =>
      (aset_X t w__0)
       : M (unit)
    else
      (aget_X 64 t) >>= fun w__1 : mword 64 =>
      (AArch64_SysInstr sys_op0 sys_op1 sys_crn sys_crm sys_op2 w__1)
       : M (unit))
    : M (unit).

Definition system_sysops_decode
(Rt : mword 5) (op2 : mword 3) (CRm : mword 4) (CRn : mword 4) (op1 : mword 3) (op0 : mword 2)
(L : mword 1)
: M (unit) :=
   write_reg __unconditional_ref true >>
   (AArch64_CheckSystemAccess ('b"01"  : mword 2) op1 CRn CRm op2 Rt L) >>
   let t := projT1 (uint Rt) in
   let sys_op0 := 1 in
   let sys_op1 := projT1 (uint op1) in
   let sys_op2 := projT1 (uint op2) in
   let sys_crn := projT1 (uint CRn) in
   let sys_crm := projT1 (uint CRm) in
   let has_result := eq_vec L ('b"1"  : mword 1) in
   (__PostDecode tt) >>
   (system_sysops has_result sys_crm sys_crn sys_op0 sys_op1 sys_op2 t)
    : M (unit).

