Definition FPDecodeRounding (rmode : mword 2) : M (FPRounding) :=
   let b__0 := rmode in
   (if eq_vec b__0 ('b"00"  : mword 2) then returnm FPRounding_TIEEVEN
    else if eq_vec b__0 ('b"01"  : mword 2) then returnm FPRounding_POSINF
    else if eq_vec b__0 ('b"10"  : mword 2) then returnm FPRounding_NEGINF
    else if eq_vec b__0 ('b"11"  : mword 2) then returnm FPRounding_ZERO
    else
      assert_exp' false "Pattern match failure at model/aarch64_float.sail 85:4 - 98:5" >>= fun _ =>
      exit tt)
    : M (FPRounding).

Definition FPRoundingMode (fpcr : mword 32) : M (FPRounding) :=
