Definition aget_Vpart (width : Z) (n : Z) (part : Z)
`{ArithFact ((n >=? 0) && ((n <=? 31) && member_Z_list part [0; 1]))}
: M (mword width) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 31)) "model/aarch64_float.sail 130:27 - 130:28" >>= fun _ =>
   assert_exp' (orb (Z.eqb part 0) (Z.eqb part 1)) "model/aarch64_float.sail 131:32 - 131:33" >>= fun _ =>
   (if sumbool_of_bool (Z.eqb part 0) then
      assert_exp' (orb (Z.eqb (projT1 (__id width)) 8)
                     (orb (Z.eqb (projT1 (__id width)) 16)
                        (orb (Z.eqb (projT1 (__id width)) 32) (Z.eqb (projT1 (__id width)) 64)))) "model/aarch64_float.sail 133:71 - 133:72" >>= fun _ =>
      read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
      returnm (slice (vec_access_dec w__0 n) 0 (projT1 (__id width)))
    else
      assert_exp' (orb (Z.eqb (projT1 (__id width)) 32) (Z.eqb (projT1 (__id width)) 64)) "model/aarch64_float.sail 136:42 - 136:43" >>= fun _ =>
      read_reg _V_ref >>= fun w__1 : vec (mword 128) 32 =>
      returnm (slice (vec_access_dec w__1 n) (projT1 (__id width)) (projT1 (__id width))))
    : M (mword width).

