Definition UnsignedSatQ (i : Z) (N : Z) `{ArithFact (N >=? 0)} : M ((mword N * bool)) :=
   (undefined_int tt) >>= fun w__0 : Z =>
   let result : Z := w__0  : Z in
   (undefined_bool tt) >>= fun w__1 : bool =>
   let saturated : bool := w__1  : bool in
   let '(result, saturated) :=
     (if sumbool_of_bool (Z.gtb i (Z.sub (projT1 (pow2 N)) 1)) then
        let result : Z := Z.sub (projT1 (pow2 N)) 1 in
        let saturated : bool := true in
        (result, saturated)
      else
        let '(result, saturated) :=
          (if sumbool_of_bool (Z.ltb i 0) then
             let result : Z := 0 in
             let saturated : bool := true in
             (result, saturated)
           else
             let result : Z := i in
             let saturated : bool := false in
             (result, saturated))
           : (Z * bool) in
        (result, saturated))
      : (Z * bool) in
   returnm (__GetSlice_int N result 0, saturated).

