Definition LowestSetBit {N : Z} (x : mword N) `{ArithFact (N >=? 0)} : M (Z) :=
   catch_early_return
     ((let loop_i_lower := 0 in
     let loop_i_upper := Z.sub (length x) 1 in
     (foreach_ZM_up loop_i_lower loop_i_upper 1 tt
       (fun i _ _ =>
         (if eq_vec (vec_of_bits [access_vec_dec x i]  : mword 1) ('b"1"  : mword 1) then
            (early_return (i  : Z) : MR unit Z)
             : MR (unit) _
          else returnm tt)
          : MR (unit) _))) >>
     returnm (length x)).

