   (let loop_i_lower := 0 in
   let loop_i_upper := Z.sub (length op1) 1 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 result
     (fun i _ result =>
       (if eq_vec (vec_of_bits [access_vec_dec op1 i]  : mword 1) ('b"1"  : mword 1) then
          (LSL (autocast (autocast extended_op2)) i) >>= fun w__1 : mword (N + M') =>
          let result : bits (N + M') := xor_vec result w__1 in
