        else returnm result)
        : M (mword (N + M')))))
    : M (mword (N + M')).

Definition FPOnePointFive (N : Z) (sign : mword 1) : M (mword N) :=
   assert_exp' (orb (Z.eqb (projT1 (__id N)) 16)
                  (orb (Z.eqb (projT1 (__id N)) 32) (Z.eqb (projT1 (__id N)) 64))) "model/aarch64_vector.sail 212:41 - 212:42" >>= fun _ =>
   let E :=
     if sumbool_of_bool (Z.eqb (projT1 (__id N)) 16) then 5
     else if sumbool_of_bool (Z.eqb (projT1 (__id N)) 32) then 8
     else 11 in
   let F := Z.sub (projT1 (__id N)) (Z.add E 1) in
   let exp : bits E := autocast (concat_vec ('b"0"  : mword 1) (Ones (Z.sub E 1))) in
   let frac : bits (N - 1 - E) := autocast (concat_vec ('b"1"  : mword 1) (zeros (Z.sub F 1))) in
   returnm (autocast (autocast (concat_vec (concat_vec sign exp) frac))).

Definition RecipSqrtEstimate (a__arg : Z) : M (Z) :=
   let a : Z := a__arg in
   assert_exp' (andb (Z.leb 128 a) (Z.ltb a 512)) "model/aarch64_vector.sail 224:29 - 224:30" >>= fun _ =>
   let a : Z :=
     if sumbool_of_bool (Z.ltb a 256) then Z.add (Z.mul a 2) 1
     else
       let a : Z := shl_int (shr_int a 1) 1 in
       Z.mul (Z.add a 1) 2 in
   let b : Z := 512 in
   (whileMT
     b
     (fun b => Z.sub (projT1 (pow2 28)) b)
     (fun b => returnm (Z.ltb (Z.mul (Z.mul a (Z.add b 1)) (Z.add b 1)) (projT1 (pow2 28))))
     (fun b =>
       let b : Z := Z.add b 1 in
       returnm b)) >>= fun b : Z =>
   let r : Z := projT1 (ediv_with_eq (Z.add b 1) 2) in
   assert_exp' (andb (Z.leb 256 r) (Z.ltb r 512)) "model/aarch64_vector.sail 236:29 - 236:30" >>= fun _ =>
   returnm r.

Definition UnsignedRSqrtEstimate {N : Z} (operand : mword N) `{ArithFact (N >=? 0)} : M (mword N) :=
