   (if sumbool_of_bool (Z.eqb shift 0) then returnm x
    else (ROR x (Z.sub (length x) shift))  : M (mword N))
    : M (mword N).

Definition SHA256hash (X__arg : mword 128) (Y__arg : mword 128) (W : mword 128) (part1 : bool)
: M (mword 128) :=
   let X := X__arg in
   let Y := Y__arg in
   (undefined_bitvector 32) >>= fun w__0 : mword 32 =>
   let chs : bits 32 := w__0  : bits 32 in
   (undefined_bitvector 32) >>= fun w__1 : mword 32 =>
   let maj : bits 32 := w__1  : bits 32 in
   (undefined_bitvector 32) >>= fun w__2 : mword 32 =>
   let t : bits 32 := w__2  : bits 32 in
   (let loop_e_lower := 0 in
   let loop_e_upper := 3 in
   (foreach_ZM_up loop_e_lower loop_e_upper 1 (X, Y, chs, maj, t)
     (fun e _ '(X, Y, chs, maj, t) =>
       let chs := (SHAchoose (slice Y 0 32) (slice Y 32 32) (slice Y 64 32))  : mword 32 in
       let maj := (SHAmajority (slice X 0 32) (slice X 32 32) (slice X 64 32))  : mword 32 in
       (SHAhashSIGMA1 (slice Y 0 32)) >>= fun w__3 : mword 32 =>
       let t :=
         (add_vec (add_vec (add_vec (slice Y 96 32) w__3) chs) (aget_Elem__1 W e 32))
          : mword 32 in
       let X := (set_slice 128 32 X 96 (add_vec t (slice X 96 32)))  : mword 128 in
       (SHAhashSIGMA0 (slice X 0 32)) >>= fun w__4 : mword 32 =>
       let Y : mword 128 := set_slice 128 32 Y 96 (add_vec (add_vec t w__4) maj) in
       (ROL (concat_vec Y X) 32) >>= fun __tc1 =>
       let Y : mword 128 := slice __tc1 128 128 in
       let X : mword 128 := slice __tc1 0 128 in
       returnm (X, Y, chs, maj, t)))) >>= fun '((X, Y, chs, maj, t)
   : (mword 128 * mword 128 * mword 32 * mword 32 * mword 32)) =>
   returnm (if sumbool_of_bool part1 then X else Y).

Definition FPProcessNaNs3H {N : Z}
(type1 : FPType) (type2 : FPType) (type3 : FPType) (op1 : mword N) (op2 : mword (ZEuclid.div N 2))
(op3 : mword (ZEuclid.div N 2)) (fpcr : mword 32) `{ArithFact (N >=? 0)}
