   let done : bool := w__1  : bool in
   (if generic_eq type1 FPType_SNaN then
      let done := true  : bool in
      (FPProcessNaN type1 op1 fpcr) >>= fun w__2 : mword N =>
      let result : bits N := w__2 in
      returnm (done, result)
    else if generic_eq type2 FPType_SNaN then
      let done := true  : bool in
      (FPProcessNaN type2 op2 fpcr) >>= fun w__3 : mword (ZEuclid.div N 2) =>
      (FPConvertNaN (length op1) w__3) >>= fun w__4 : mword N =>
      let result : bits N := w__4 in
      returnm (done, result)
    else if generic_eq type3 FPType_SNaN then
      let done := true  : bool in
      (FPProcessNaN type3 op3 fpcr) >>= fun w__5 : mword (ZEuclid.div N 2) =>
      (FPConvertNaN (length op1) w__5) >>= fun w__6 : mword N =>
      let result : bits N := w__6 in
      returnm (done, result)
    else if generic_eq type1 FPType_QNaN then
      let done := true  : bool in
      (FPProcessNaN type1 op1 fpcr) >>= fun w__7 : mword N =>
      let result : bits N := w__7 in
      returnm (done, result)
    else if generic_eq type2 FPType_QNaN then
      let done := true  : bool in
      (FPProcessNaN type2 op2 fpcr) >>= fun w__8 : mword (ZEuclid.div N 2) =>
      (FPConvertNaN (length op1) w__8) >>= fun w__9 : mword N =>
      let result : bits N := w__9 in
      returnm (done, result)
    else if generic_eq type3 FPType_QNaN then
      let done := true  : bool in
      (FPProcessNaN type3 op3 fpcr) >>= fun w__10 : mword (ZEuclid.div N 2) =>
      (FPConvertNaN (length op1) w__10) >>= fun w__11 : mword N =>
      let result : bits N := w__11 in
      returnm (done, result)
    else
      let done : bool := false in
      let result : bits N := zeros (length op1) in
      returnm (done, result))
    : M ((bool * mword N)).

Definition AdvSIMDExpandImm (op : mword 1) (cmode : mword 4) (imm8 : mword 8) : M (mword 64) :=
