   let imm8a : bits 8 := w__2  : bits 8 in
   (undefined_bitvector 8) >>= fun w__3 : mword 8 =>
   let imm8b : bits 8 := w__3  : bits 8 in
   (undefined_bitvector 8) >>= fun w__4 : mword 8 =>
   let imm8c : bits 8 := w__4  : bits 8 in
