   let imm8g : bits 8 := w__8  : bits 8 in
   (undefined_bitvector 8) >>= fun w__9 : mword 8 =>
   let imm8h : bits 8 := w__9  : bits 8 in
   let b__0 := slice cmode 1 3 in
   (if eq_vec b__0 ('b"000"  : mword 3) then
      let imm64 : bits 64 := replicate_bits (concat_vec (zeros 24) imm8) 2 in
      returnm imm64
    else if eq_vec b__0 ('b"001"  : mword 3) then
      let imm64 : bits 64 := replicate_bits (concat_vec (concat_vec (zeros 16) imm8) (zeros 8)) 2 in
      returnm imm64
    else if eq_vec b__0 ('b"010"  : mword 3) then
      let imm64 : bits 64 := replicate_bits (concat_vec (concat_vec (zeros 8) imm8) (zeros 16)) 2 in
      returnm imm64
    else if eq_vec b__0 ('b"011"  : mword 3) then
      let imm64 : bits 64 := replicate_bits (concat_vec imm8 (zeros 24)) 2 in
      returnm imm64
    else if eq_vec b__0 ('b"100"  : mword 3) then
