   (undefined_bitvector (projT1 (__id datasize))) >>= fun w__0 : mword datasize =>
   let result : bits datasize := w__0  : bits datasize in
   let round_const := if sumbool_of_bool round then shl_int 1 (Z.sub esize 1) else 0 in
   (undefined_bitvector (Z.mul 2 (projT1 (__id esize)))) >>= fun w__1 : mword (2 * esize) =>
   let element1 : bits (2 * esize) := w__1  : bits (2 * esize) in
