       let element2 := (aget_Elem__1 operand2 e (Z.mul 2 esize))  : mword (2 * esize) in
       let sum : mword (2 * esize) :=
         if sumbool_of_bool sub_op then sub_vec element1 element2
         else add_vec element1 element2 in
       let sum := (add_vec_int sum round_const)  : mword (2 * esize) in
       (aset_Elem__1 result e esize (slice sum esize esize)) >>= fun w__4 : mword datasize =>
       let result : bits datasize := w__4 in
