Definition aset_DBGDTR_EL0 {N : Z} (value_name__arg : mword N) `{ArithFact (N >=? 0)} : M (unit) :=
   let value_name := value_name__arg in
   assert_exp' (orb (Z.eqb (length value_name__arg) 32) (Z.eqb (length value_name__arg) 64)) "model/aarch32.sail 1188:30 - 1188:31" >>= fun _ =>
   ((read_reg EDSCR_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
   (if eq_vec (vec_of_bits [access_vec_dec w__0 29]  : mword 1) ('b"1"  : mword 1) then
      (undefined_bitvector (length value_name__arg))
       : M (mword N)
    else returnm value_name) >>= fun value_name : mword N =>
   (if sumbool_of_bool (Z.eqb (length value_name__arg) 64) then
      write_reg DTRRX_ref (slice value_name 32 32)
       : M (unit)
    else returnm tt) >>
   write_reg DTRTX_ref (slice value_name 0 32) >>
   ((read_reg EDSCR_ref)  : M (mword 32)) >>= fun w__2 : mword 32 =>
   write_reg EDSCR_ref (set_slice 32 1 w__2 29 ('b"1"  : mword 1))
    : M (unit).

Definition aget_DBGDTR_EL0 (N : Z) : M (mword N) :=
   assert_exp' (orb (Z.eqb (projT1 (__id N)) 32) (Z.eqb (projT1 (__id N)) 64)) "model/aarch32.sail 1206:30 - 1206:31" >>= fun _ =>
   (undefined_bitvector (projT1 (__id N))) >>= fun w__0 : mword N =>
   let result : bits N := w__0  : bits N in
   ((read_reg EDSCR_ref)  : M (mword 32)) >>= fun w__1 : mword 32 =>
   (if eq_vec (vec_of_bits [access_vec_dec w__1 30]  : mword 1) ('b"0"  : mword 1) then
      (undefined_bitvector (projT1 (__id N)))
       : M (mword N)
    else
      (if sumbool_of_bool (Z.eqb (projT1 (__id N)) 64) then
         ((read_reg DTRTX_ref)  : M (mword 32)) >>= fun w__3 : mword 32 =>
         let result : bits N := set_slice (projT1 (__id N)) 32 result 32 w__3 in
         returnm result
       else returnm result) >>= fun result : mword N =>
      ((read_reg DTRRX_ref)  : M (mword 32)) >>= fun w__4 : mword 32 =>
      let result : bits N := set_slice (projT1 (__id N)) 32 result 0 w__4 in
      returnm result) >>= fun result : mword N =>
   ((read_reg EDSCR_ref)  : M (mword 32)) >>= fun w__5 : mword 32 =>
   write_reg EDSCR_ref (set_slice 32 1 w__5 30 ('b"0"  : mword 1)) >> returnm result.

