    else read_reg PSTATE_ref >>= fun w__1 : ProcState => returnm (projT1 (uint w__1.(ProcState_T))))
    : M (Z).

Definition __PreExecute (pc : Z) (len : Z) (instr : mword 32) : M (bool) :=
   write_reg __currentInstrLength_ref len >>
   write_reg __currentInstr_ref instr >>
   write_reg __PC_changed_ref false >>
   (and_boolM
      (read_reg PSTATE_ref >>= fun w__0 : ProcState =>
       returnm ((eq_vec w__0.(ProcState_nRW) ('b"1"  : mword 1))  : bool))
      (read_reg PSTATE_ref >>= fun w__1 : ProcState =>
       returnm ((eq_vec w__1.(ProcState_T) ('b"1"  : mword 1))  : bool))) >>= fun w__2 : bool =>
   write_reg ShouldAdvanceIT_ref w__2 >> returnm true.

Definition LastInITBlock '(tt : unit) : M (bool) :=
