Definition DecodeImmShift (typ : mword 2) (imm5 : mword 5) : M ((SRType * Z)) :=
   (undefined_int tt) >>= fun w__0 : Z =>
   let shift_n : Z := w__0  : Z in
   (undefined_SRType tt) >>= fun w__1 : SRType =>
   let shift_t : SRType := w__1  : SRType in
   let b__0 := typ in
   (if eq_vec b__0 ('b"00"  : mword 2) then
      let shift_t : SRType := SRType_LSL in
      let shift_n : Z := projT1 (uint imm5) in
      returnm (shift_n, shift_t)
    else if eq_vec b__0 ('b"01"  : mword 2) then
      let shift_t : SRType := SRType_LSR in
      let shift_n : Z := if eq_vec imm5 ('b"00000"  : mword 5) then 32 else projT1 (uint imm5) in
      returnm (shift_n, shift_t)
    else if eq_vec b__0 ('b"10"  : mword 2) then
      let shift_t : SRType := SRType_ASR in
      let shift_n : Z := if eq_vec imm5 ('b"00000"  : mword 5) then 32 else projT1 (uint imm5) in
      returnm (shift_n, shift_t)
    else if eq_vec b__0 ('b"11"  : mword 2) then
      let '(shift_n, shift_t) :=
        (if eq_vec imm5 ('b"00000"  : mword 5) then
           let shift_t : SRType := SRType_RRX in
           let shift_n : Z := 1 in
           (shift_n, shift_t)
         else
           let shift_t : SRType := SRType_ROR in
           let shift_n : Z := projT1 (uint imm5) in
           (shift_n, shift_t))
         : (Z * SRType) in
      returnm (shift_n, shift_t)
    else
      assert_exp' false "Pattern match failure at model/aarch32.sail 1254:4 - 1276:5" >>= fun _ =>
      exit tt) >>= fun '((shift_n, shift_t)
   : (Z * SRType)) =>
   returnm (shift_t, shift_n).

Definition AArch32_PAROuterAttrs (memattrs : MemoryAttributes) : M (mword 2) :=
   (undefined_bitvector 2) >>= fun w__0 : mword 2 =>
   let result : bits 2 := w__0  : bits 2 in
   (if generic_eq memattrs.(MemoryAttributes_typ) MemType_Device then
      (undefined_bitvector 2)
       : M (mword 2)
    else
      let outer : MemAttrHints := memattrs.(MemoryAttributes_outer) in
      let result : mword 2 :=
        if eq_vec outer.(MemAttrHints_attrs) MemAttr_NC then 'b"00"  : mword 2
        else if andb (eq_vec outer.(MemAttrHints_attrs) MemAttr_WB)
                  (eq_vec (vec_of_bits [access_vec_dec outer.(MemAttrHints_hints) 0]  : mword 1)
                     ('b"1"
                      : mword 1)) then
          'b"01"
           : mword 2
        else if andb (eq_vec outer.(MemAttrHints_attrs) MemAttr_WT)
                  (eq_vec (vec_of_bits [access_vec_dec outer.(MemAttrHints_hints) 0]  : mword 1)
                     ('b"0"
                      : mword 1)) then
          'b"10"
           : mword 2
        else if andb (eq_vec outer.(MemAttrHints_attrs) MemAttr_WB)
                  (eq_vec (vec_of_bits [access_vec_dec outer.(MemAttrHints_hints) 0]  : mword 1)
                     ('b"0"
                      : mword 1)) then
          'b"11"
           : mword 2
        else result in
      returnm result)
    : M (mword 2).

Definition AArch32_PARInnerAttrs (memattrs : MemoryAttributes) : M (mword 3) :=
   (undefined_bitvector 3) >>= fun w__0 : mword 3 =>
   let result : bits 3 := w__0  : bits 3 in
   let result : mword 3 :=
     if generic_eq memattrs.(MemoryAttributes_typ) MemType_Device then
       if generic_eq memattrs.(MemoryAttributes_device) DeviceType_nGnRnE then 'b"001"  : mword 3
       else if generic_eq memattrs.(MemoryAttributes_device) DeviceType_nGnRE then
         'b"011"
          : mword 3
       else result
     else
       let inner : MemAttrHints := memattrs.(MemoryAttributes_inner) in
       if eq_vec inner.(MemAttrHints_attrs) MemAttr_NC then 'b"000"  : mword 3
       else if andb (eq_vec inner.(MemAttrHints_attrs) MemAttr_WB)
                 (eq_vec (vec_of_bits [access_vec_dec inner.(MemAttrHints_hints) 0]  : mword 1)
                    ('b"1"
                     : mword 1)) then
         'b"101"
          : mword 3
       else if eq_vec inner.(MemAttrHints_attrs) MemAttr_WT then 'b"110"  : mword 3
       else if andb (eq_vec inner.(MemAttrHints_attrs) MemAttr_WB)
                 (eq_vec (vec_of_bits [access_vec_dec inner.(MemAttrHints_hints) 0]  : mword 1)
                    ('b"0"
                     : mword 1)) then
         'b"111"
          : mword 3
       else result in
   returnm result.

