Definition __UpdateSystemCounter '(tt : unit) : M (unit) :=
   ((read_reg CNTCR_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
   (if eq_vec (vec_of_bits [access_vec_dec w__0 0]  : mword 1) ('b"1"  : mword 1) then
      ((read_reg CNTCV_ref)  : M (mword 64)) >>= fun w__1 : mword 64 =>
      write_reg CNTCV_ref (__GetSlice_int 64 (Z.add (projT1 (uint w__1)) 1) 0)
       : M (unit)
    else returnm tt)
    : M (unit).

Definition StandardFPSCRValue '(tt : unit) : M (mword 32) :=
   ((read_reg FPSCR_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
   ((read_reg FPSCR_ref)  : M (mword 32)) >>= fun w__1 : mword 32 =>
   returnm (concat_vec
              (concat_vec
                 (concat_vec
                    (concat_vec ('b"00000"  : mword 5)
                       (vec_of_bits [access_vec_dec w__0 26]  : mword 1)) ('b"110000"  : mword 6))
                 (vec_of_bits [access_vec_dec w__1 19]  : mword 1))
              ('b"0000000000000000000"
               : mword 19)).

Definition RRX_C {N : Z} (x : mword N) (carry_in : mword 1)
`{ArithFact ((N >=? 0) && ((N - 1) >=? 0))}
: (mword N * mword 1) :=
   let result : bits N := autocast (concat_vec carry_in (slice x 1 (Z.sub (length x) 1))) in
   let carry_out := (vec_of_bits [access_vec_dec x 0]  : mword 1) in
   (result, carry_out).

Definition AArch32_SetLSInstructionSyndrome
(size : Z) (sign_extend : bool) (Rt : Z) (acq_rel : bool)
`{ArithFact ((Rt >=? 0) && ((Rt <=? 14) && member_Z_list size [1; 2; 4; 8]))}
: M (unit) :=
   (or_boolM
      (read_reg PSTATE_ref >>= fun w__0 : ProcState =>
       returnm ((eq_vec w__0.(ProcState_EL) EL0)  : bool))
      (read_reg PSTATE_ref >>= fun w__1 : ProcState =>
       returnm ((eq_vec w__1.(ProcState_EL) EL1)  : bool))) >>= fun w__2 : bool =>
   (if sumbool_of_bool w__2 then
      read_reg PSTATE_ref >>= fun w__3 : ProcState =>
      (LookUpRIndex Rt w__3.(ProcState_M')) >>= fun '(existT _ w__4 _ : {m : Z & ArithFact ((0 <=? m) &&
        (m <=? 30))}) =>
      (MakeLSInstructionSyndrome size sign_extend w__4 false acq_rel) >>= fun w__5 : mword 11 =>
      write_reg __LSISyndrome_ref w__5
       : M (unit)
    else returnm tt)
    : M (unit).

Definition aset_S (n : Z) (value_name : mword 32) `{ArithFact ((n >=? 0) && (n <=? 31))} : M (unit) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 31)) "model/aarch32.sail 1740:27 - 1740:28" >>= fun _ =>
   let base := Z.mul (projT1 (emod_with_eq n 4)) 32 in
   read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
   let __tc1 : bits 128 := vec_access_dec w__0 (projT1 (ediv_with_eq n 4)) in
   let __tc1 := set_slice 128 32 __tc1 base value_name in
   read_reg _V_ref >>= fun w__1 : vec (mword 128) 32 =>
   write_reg _V_ref (vec_update_dec_loose w__1 (projT1 (ediv_with_eq n 4)) __tc1)
    : M (unit).

Definition aset_D (n : Z) (value_name : mword 64) `{ArithFact ((n >=? 0) && (n <=? 31))} : M (unit) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 31)) "model/aarch32.sail 1754:27 - 1754:28" >>= fun _ =>
   let base := Z.mul (projT1 (emod_with_eq n 2)) 64 in
   read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
   let __tc1 : bits 128 := vec_access_dec w__0 (projT1 (ediv_with_eq n 2)) in
   let __tc1 := set_slice 128 64 __tc1 base value_name in
   read_reg _V_ref >>= fun w__1 : vec (mword 128) 32 =>
   write_reg _V_ref (vec_update_dec_loose w__1 (projT1 (ediv_with_eq n 2)) __tc1)
    : M (unit).

Definition aget_S (n : Z) `{ArithFact ((n >=? 0) && (n <=? 31))} : M (mword 32) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 31)) "model/aarch32.sail 1768:27 - 1768:28" >>= fun _ =>
   let base : Z := Z.mul (projT1 (emod_with_eq n 4)) 32 in
   read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
   returnm (slice (vec_access_dec w__0 (projT1 (ediv_with_eq n 4))) base 32).

Definition aget_Qin (n : Z) `{ArithFact ((n >=? 0) && (n <=? 15))} : M (mword 128) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 15)) "model/aarch32.sail 1779:27 - 1779:28" >>= fun _ =>
   (aget_Din (Z.add (Z.mul 2 n) 1)) >>= fun w__0 : mword 64 =>
   (aget_Din (Z.mul 2 n)) >>= fun w__1 : mword 64 => returnm (concat_vec w__0 w__1).

Definition aget_D (n : Z) `{ArithFact ((n >=? 0) && (n <=? 31))} : M (mword 64) :=
   assert_exp' (andb (Z.geb n 0) (Z.leb n 31)) "model/aarch32.sail 1789:27 - 1789:28" >>= fun _ =>
   let base : Z := Z.mul (projT1 (emod_with_eq n 2)) 64 in
   read_reg _V_ref >>= fun w__0 : vec (mword 128) 32 =>
   returnm (slice (vec_access_dec w__0 (projT1 (ediv_with_eq n 2))) base 64).

