Definition ClearLSInstructionSyndrome '(tt : unit) : M (unit) :=
   write_reg __LSISyndrome_ref (zeros 11)  : M (unit).

Definition __EndCycle '(tt : unit) : M (unit) :=
   (untilMT
     tt
     (fun _ => 1)
     (fun _ => returnm true)
     (fun _ =>
       (and_boolM
          (((read_reg _ScheduleIRQ_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
           returnm ((eq_vec (slice w__0 0 32) ((zero_vector 32 0)  : mword 32))  : bool))
          (read_reg ScheduledIRQ_ref
           : M (bool))) >>= fun w__2 : bool =>
       (if sumbool_of_bool w__2 then
          write_reg _IRQPending_ref true >>
          write_reg ScheduledIRQ_ref false >> (__WakeupRequest tt)  : M (unit)
        else returnm tt) >>
       ((read_reg _ScheduleIRQ_ref)  : M (mword 32)) >>= fun w__3 : mword 32 =>
       (if sumbool_of_bool (Z.gtb (projT1 (uint (slice w__3 0 32))) 0) then
          ((read_reg _ScheduleIRQ_ref)  : M (mword 32)) >>= fun w__4 : mword 32 =>
          ((read_reg _ScheduleIRQ_ref)  : M (mword 32)) >>= fun w__5 : mword 32 =>
          write_reg _ScheduleIRQ_ref (set_slice 32 32 w__4 0 (sub_vec_int (slice w__5 0 32) 1))
           : M (unit)
        else returnm tt)
        : M (unit))) >>
   (untilMT
     tt
     (fun _ => 1)
     (fun _ => returnm true)
     (fun _ =>
       (and_boolM
          (((read_reg _ScheduleFIQ_ref)  : M (mword 32)) >>= fun w__6 : mword 32 =>
           returnm ((eq_vec (slice w__6 0 32) ((zero_vector 32 0)  : mword 32))  : bool))
          (read_reg ScheduledFIQ_ref
           : M (bool))) >>= fun w__8 : bool =>
       (if sumbool_of_bool w__8 then
          write_reg _FIQPending_ref true >>
          write_reg ScheduledFIQ_ref false >> (__WakeupRequest tt)  : M (unit)
        else returnm tt) >>
       ((read_reg _ScheduleFIQ_ref)  : M (mword 32)) >>= fun w__9 : mword 32 =>
       (if sumbool_of_bool (Z.gtb (projT1 (uint (slice w__9 0 32))) 0) then
          ((read_reg _ScheduleFIQ_ref)  : M (mword 32)) >>= fun w__10 : mword 32 =>
          ((read_reg _ScheduleFIQ_ref)  : M (mword 32)) >>= fun w__11 : mword 32 =>
          write_reg _ScheduleFIQ_ref (set_slice 32 32 w__10 0 (sub_vec_int (slice w__11 0 32) 1))
           : M (unit)
        else returnm tt)
        : M (unit))) >>
   (untilMT
     tt
     (fun _ => 1)
     (fun _ => returnm true)
     (fun _ => (ClearLSInstructionSyndrome tt)  : M (unit))) >>
   (untilMT tt (fun _ => 1) (fun _ => returnm true) (fun _ => returnm tt  : M (unit))).

Definition __CycleEnd '(tt : unit) : M (unit) := (__EndCycle tt)  : M (unit).

Definition __SetConfig (arg : string) (value_name : Z) : M (unit) :=
   (match tt with
    | tt =>
       (if generic_eq arg "trickbox_base" then returnm tt  : M (unit)
        else if generic_eq arg "cpu.has_arm_v8-1" then
          (__ConfigureV81Features (Z.eqb value_name 1))
           : M (unit)
        else if generic_eq arg "cpu.has_arm_v8-2" then
          (__ConfigureV82Features (Z.eqb value_name 1))
           : M (unit)
        else if generic_eq arg "cpu.has_arm_v8-3" then
