          ((read_reg LORID_EL1_ref)  : M (mword 32)) >>= fun w__0 : mword 32 =>
          write_reg LORID_EL1_ref (set_slice 32 8 w__0 0 (__GetSlice_int 8 value_name 0))
           : M (unit)
        else if generic_eq arg "cpu.num_loregion_descriptors" then
