          write_reg LORID_EL1_ref (set_slice 32 8 w__1 16 (__GetSlice_int 8 value_name 0))
           : M (unit)
        else if generic_eq arg "cpu.has_pstate_pan" then returnm tt  : M (unit)
        else if generic_eq arg "cpu.has_16bit_vmids" then returnm tt  : M (unit)
        else if generic_eq arg "cpu.cpu0.enable_crc32" then returnm tt  : M (unit)
        else if generic_eq arg "cpu.has_dot_product" then returnm tt  : M (unit)
        else if generic_eq arg "cpu.has_fp16" then returnm tt  : M (unit)
