Definition SETPAN_Op_A (value_name : mword 1) : M (unit) :=
   read_reg PSTATE_ref >>= fun w__0 : ProcState =>
   (if neq_vec w__0.(ProcState_EL) EL0 then
      read_reg PSTATE_ref >>= fun w__1 : ProcState =>
      write_reg PSTATE_ref {[ w__1 with ProcState_PAN := value_name ]}
       : M (unit)
    else returnm tt)
    : M (unit).

Definition T32ExpandImm_C (imm12 : mword 12) (carry_in : mword 1) : M ((mword 32 * mword 1)) :=
   (undefined_bitvector 1) >>= fun w__0 : mword 1 =>
   let carry_out : bits 1 := w__0  : bits 1 in
   (undefined_bitvector 32) >>= fun w__1 : mword 32 =>
   let imm32 : bits 32 := w__1  : bits 32 in
   (undefined_bitvector 32) >>= fun w__2 : mword 32 =>
   let unrotated_value : bits 32 := w__2  : bits 32 in
   (if eq_vec (slice imm12 10 2) ('b"00"  : mword 2) then
      let b__0 := slice imm12 8 2 in
      (if eq_vec b__0 ('b"00"  : mword 2) then (ZeroExtend__0 (slice imm12 0 8) 32)  : M (mword 32)
       else if eq_vec b__0 ('b"01"  : mword 2) then
         let imm32 : bits 32 :=
           concat_vec
             (concat_vec (concat_vec (Ox"00"  : mword 8) (slice imm12 0 8)) (Ox"00"  : mword 8))
             (slice imm12 0 8) in
         returnm imm32
       else if eq_vec b__0 ('b"10"  : mword 2) then
         let imm32 : bits 32 :=
           concat_vec
             (concat_vec (concat_vec (slice imm12 0 8) (Ox"00"  : mword 8)) (slice imm12 0 8))
             (Ox"00"
              : mword 8) in
         returnm imm32
       else if eq_vec b__0 ('b"11"  : mword 2) then
         let imm32 : bits 32 :=
           concat_vec
             (concat_vec (concat_vec (slice imm12 0 8) (slice imm12 0 8)) (slice imm12 0 8))
             (slice imm12 0 8) in
         returnm imm32
       else
         assert_exp' false "Pattern match failure at model/aarch32.sail 2345:8 - 2358:9" >>= fun _ =>
         exit tt) >>= fun imm32 : mword 32 =>
      let carry_out : bits 1 := carry_in in
      returnm (carry_out, imm32)
    else
      (ZeroExtend__0 (concat_vec ('b"1"  : mword 1) (slice imm12 0 7)) 32) >>= fun w__4 : mword 32 =>
      let unrotated_value := w__4  : mword 32 in
      (ROR_C unrotated_value (projT1 (uint (slice imm12 7 5)))) >>= fun w__5 : (mword 32 * mword 1) =>
      let '(tup__0, tup__1) := w__5  : (mword 32 * mword 1) in
      let imm32 : bits 32 := tup__0 in
      let carry_out : bits 1 := tup__1 in
      returnm (carry_out, imm32)) >>= fun '((carry_out, imm32)
   : (mword 1 * mword 32)) =>
   returnm (imm32, carry_out).

Definition T32ExpandImm (imm12 : mword 12) : M (mword 32) :=
   (undefined_bitvector 1) >>= fun w__0 : mword 1 =>
   let __anon1 : bits 1 := w__0  : bits 1 in
   (undefined_bitvector 32) >>= fun w__1 : mword 32 =>
   let imm32 : bits 32 := w__1  : bits 32 in
   read_reg PSTATE_ref >>= fun w__2 : ProcState =>
   (T32ExpandImm_C imm12 w__2.(ProcState_C)) >>= fun w__3 : (mword 32 * mword 1) =>
   let '(tup__0, tup__1) := w__3  : (mword 32 * mword 1) in
   let imm32 : bits 32 := tup__0 in
   let __anon1 : bits 1 := tup__1 in
   returnm imm32.

Definition AArch32_PARFaultStatusSD (fault : FaultRecord) : M (mword 6) :=
   (AArch32_FaultStatusSD true fault) >>= fun syndrome : bits 32 =>
   returnm (concat_vec (subrange_vec_dec syndrome 12 12)
              (concat_vec (subrange_vec_dec syndrome 10 10)
                 (concat_vec (subrange_vec_dec syndrome 0 0) (subrange_vec_dec syndrome 31 29)))).

Definition AArch32_PARFaultStatusLD (fault : FaultRecord) (report_domain_fault : bool) : M (mword 6) :=
   (undefined_bitvector 32) >>= fun w__0 : mword 32 =>
   let syndrome : bits 32 := w__0  : bits 32 in
   (if sumbool_of_bool
      (andb (generic_eq fault.(FaultRecord_typ) Fault_Domain) report_domain_fault) then
      assert_exp (orb (Z.eqb fault.(FaultRecord_level) 1) (Z.eqb fault.(FaultRecord_level) 2)) "model/aarch32.sail 2389:50 - 2389:51" >>
      let syndrome : bits 32 :=
        set_slice 32 2 syndrome 0
          (if Z.eqb fault.(FaultRecord_level) 1 then 'b"01"  : mword 2
           else 'b"10"  : mword 2) in
      let syndrome : bits 32 := set_slice 32 4 syndrome 2 (Ox"F"  : mword 4) in
      returnm syndrome
    else (AArch32_FaultStatusLD true fault)  : M (mword 32)) >>= fun syndrome : mword 32 =>
   returnm (slice syndrome 0 6).

Definition AArch32_DecodeSysRegAccess (instr : mword 32)
: M ((SystemAccessType * Z * Z * Z * Z * Z * bool)) :=
   let cp_num := projT1 (uint (slice instr 8 4)) in
   (undefined_int tt) >>= fun w__0 : Z =>
   let CRm : Z := w__0  : Z in
   (undefined_int tt) >>= fun w__1 : Z =>
   let CRn : Z := w__1  : Z in
   (undefined_SystemAccessType tt) >>= fun w__2 : SystemAccessType =>
   let op : SystemAccessType := w__2  : SystemAccessType in
   (undefined_int tt) >>= fun w__3 : Z =>
   let opc1 : Z := w__3  : Z in
   (undefined_int tt) >>= fun w__4 : Z =>
   let opc2 : Z := w__4  : Z in
   (undefined_bool tt) >>= fun w__5 : bool =>
   let write : bool := w__5  : bool in
   let '(CRm, CRn, op, opc1, opc2, write) :=
     (if andb
           (andb (neq_vec (slice instr 28 4) (Ox"F"  : mword 4))
              (eq_vec (slice instr 24 4) (Ox"E"  : mword 4)))
           (eq_vec (vec_of_bits [access_vec_dec instr 4]  : mword 1) ('b"1"  : mword 1)) then
        let op : SystemAccessType := SystemAccessType_RT in
        let opc1 : Z := projT1 (uint (slice instr 21 3)) in
        let opc2 : Z := projT1 (uint (slice instr 5 3)) in
        let CRn : Z := projT1 (uint (slice instr 16 4)) in
        let CRm : Z := projT1 (uint (slice instr 0 4)) in
        let write : bool :=
          eq_vec (vec_of_bits [access_vec_dec instr 20]  : mword 1) ('b"0"  : mword 1) in
        (CRm, CRn, op, opc1, opc2, write)
      else
        let '(CRm, CRn, op, opc1, write) :=
