Definition Step_System '(tt : unit) : M (unit) :=
   (try_catch ((try_catch ((Step_Timers tt)
                 : M (unit)) (fun __catch_val => match __catch_val with 
                | _ =>
                   (aget_PC tt) >>= fun w__0 : mword 64 =>
                   (get_cycle_count tt) >>= fun w__1 : Z =>
                   returnm (print
                              (String.append "Exception taken during Step_Timers.  PC="
                                 (String.append (hex_str (projT1 (uint w__0)))
                                    (String.append " cycle=" (String.append (dec_str w__1) "
")))))
                end)) >>
               read_reg PSTATE_ref >>= fun w__2 : ProcState =>
               let prevEL := w__2.(ProcState_EL) in
               read_reg PSTATE_ref >>= fun w__3 : ProcState =>
               let prevI := w__3.(ProcState_I) in
               ((read_reg CNTKCTL_EL1_ref)  : M (mword 32)) >>= fun prevCNTKCTL_EL1 =>
               ((read_reg CNTHCTL_EL2_ref)  : M (mword 32)) >>= fun prevCNTHCTL_EL2 =>
               (__Sleeping tt) >>= fun w__4 : bool =>
               (if sumbool_of_bool (negb w__4) then
                  (try_catch ((Step_CPU tt)
                    : M (unit)) (fun __catch_val => match __catch_val with 
                   | _ =>
                      (aget_PC tt) >>= fun w__5 : mword 64 =>
                      (get_cycle_count tt) >>= fun w__6 : Z =>
                      returnm (print
                                 (String.append "Exception taken during Step_CPU.  PC="
                                    (String.append (hex_str (projT1 (uint w__5)))
                                       (String.append " cycle=" (String.append (dec_str w__6) "
")))))
                   end))
                   : M (unit)
                else returnm tt) >>
               read_reg PSTATE_ref >>= fun w__7 : ProcState =>
               (if sumbool_of_bool
                  (projT1
                   (neq_int (projT1 (uint prevEL)) (projT1 (uint w__7.(ProcState_EL))))) then
                  (get_cycle_count tt) >>= fun w__8 : Z =>
                  read_reg PSTATE_ref >>= fun w__9 : ProcState =>
                  returnm (prerr_bits
                             (String.append "[Sail] "
                                (String.append (dec_str w__8) " Exception level changed to: "))
                             w__9.(ProcState_EL))
                else returnm tt) >>
               read_reg PSTATE_ref >>= fun w__10 : ProcState =>
               (if neq_vec prevI w__10.(ProcState_I) then
                  read_reg PSTATE_ref >>= fun w__11 : ProcState =>
                  let '_ := (prerr_bits "[Sail] PSTATE.I changed to: " w__11.(ProcState_I))  : unit in
                  (aget_PC tt) >>= fun w__12 : mword 64 =>
                  (get_cycle_count tt) >>= fun w__13 : Z =>
                  returnm (print
                             (String.append "   at PC="
                                (String.append (hex_str (projT1 (uint w__12)))
                                   (String.append " in cycle=" (String.append (dec_str w__13) "
")))))
                else returnm tt) >>
               ((read_reg CNTKCTL_EL1_ref)  : M (mword 32)) >>= fun w__14 : mword 32 =>
               (if neq_vec prevCNTKCTL_EL1 w__14 then
                  ((read_reg CNTKCTL_EL1_ref)  : M (mword 32)) >>= fun w__15 : mword 32 =>
                  returnm (prerr_bits "[Clock] CNTKCTL_EL1 changed to " w__15)
                else returnm tt) >>
               ((read_reg CNTHCTL_EL2_ref)  : M (mword 32)) >>= fun w__16 : mword 32 =>
               (if neq_vec prevCNTHCTL_EL2 w__16 then
                  ((read_reg CNTHCTL_EL2_ref)  : M (mword 32)) >>= fun w__17 : mword 32 =>
                  returnm (prerr_bits "[Clock] CNTHCTL_EL2 changed to " w__17)
                else returnm tt)
                : M (unit)) (fun __catch_val => match __catch_val with 
    | Error_ExceptionTaken _ =>
       (aget_PC tt) >>= fun w__18 : mword 64 =>
       (get_cycle_count tt) >>= fun w__19 : Z =>
       let '_ :=
         (print
            (String.append "Exception taken during Step_System.  PC="
               (String.append (hex_str (projT1 (uint w__18)))
                  (String.append " cycle=" (String.append (dec_str w__19) "
")))))
          : unit in
       returnm tt
    | Error_SError iesb_req => (TakeSError iesb_req)  : M (unit)
    | _ =>
       let '_ := (prerr "Exiting due to unhandled exception
")  : unit in
       exit tt
        : M (unit)
    end)) >>
   (try_catch ((__EndCycle tt)
     : M (unit)) (fun __catch_val => match __catch_val with 
    | _ =>
       (aget_PC tt) >>= fun w__20 : mword 64 =>
       (get_cycle_count tt) >>= fun w__21 : Z =>
       returnm (print
                  (String.append "Exception taken during __EndCycle.  PC="
                     (String.append (hex_str (projT1 (uint w__20)))
                        (String.append " cycle=" (String.append (dec_str w__21) "
")))))
    end))
    : M (unit).

Definition COLD_RESET : bool := true.
Hint Unfold COLD_RESET : sail.
Definition init '(tt : unit) : M (unit) := (TakeReset COLD_RESET)  : M (unit).

Axiom check_cycle_count : forall  (_ : unit) , unit.

Definition main '(tt : unit) : M (unit) :=
   (__GetVerbosity tt) >>= fun verbosity =>
   (init tt) >>
   (whileMT
     tt
     (fun _ => 100)
     (fun _ => returnm true)
     (fun _ =>
       (if eq_bit (access_vec_dec verbosity 0) B1 then
          read_reg PSTATE_ref >>= fun w__0 : ProcState =>
          read_reg PSTATE_ref >>= fun w__1 : ProcState =>
          read_reg PSTATE_ref >>= fun w__2 : ProcState =>
          read_reg PSTATE_ref >>= fun w__3 : ProcState =>
          let nzcv :=
            concat_vec w__0.(ProcState_N)
              (concat_vec w__1.(ProcState_Z') (concat_vec w__2.(ProcState_C) w__3.(ProcState_V))) in
          (get_cycle_count tt) >>= fun w__4 : Z =>
          (aget_PC tt) >>= fun w__5 : mword 64 =>
          returnm (print
                     (String.append "[Sail] "
                        (String.append (dec_str w__4)
                           (String.append " PC="
                              (String.append (hex_str (projT1 (uint w__5)))
                                 (String.append " NZCV="
                                    (String.append (hex_str (projT1 (uint nzcv))) "
")))))))
        else returnm tt) >>
       (Step_System tt) >>
       returnm (let '_ := (check_cycle_count tt)  : unit in
       tt))).

